(window.EX_CHUNKS=window.EX_CHUNKS||{})["b32"]={"刮风":[["外面刮风了，快把窗户关上。","سىرتتا شامال كۈچلۈك ئۇچۇۋاتىدۇ، تېزراق دېرىزىنى يېپىڭ.","sirtta shamal küchlük uchuwatidu, tézraq dérizini yéping."]],"洗手间":[["洗手间在走廊的尽头。","ھاجەتخانا يولنىڭ ئاخىرىدا.","hajetxana yolning axirida."]],"称心如意":[["这份礼物真是称心如意。","بۇ سوۋغات ھەقىقەتەن كۆڭۈلدىكىدەك بولدى.","bu sowghat heqiqeten köngüldikidek boldi."]],"㿠":[["面对困难，他毫不退缩，展现出坚强的意志㿠力。","قىيىنچىلىققا دۇچ كەلگەندە، ئۇ زىنھار چېكىنمەي، كۈچلۈك ئىرادىنى نامايان قىلدى.","qiyinchiliqqa duch kelgende, u zinhar chékinmey, küchlük iradini namayan qildi."]],"勠":[["团队勠力同心，终于攻克了技术难关。","گۇرۇپپا بىر نىيەت، بىر مەقسەتتە بولۇپ، ئاخىرى تېخنىكىلىق قىيىنچىلىقنى يېڭىشتى.","guruppa bir niyet, bir meqsette bolup, axiri téxnikiliq qiyinchiliqni yéngishti."]],"咠":[["这个字读“咠”。","بۇ خەت «چى» دەپ ئوقۇلىدۇ.","bu xet «chi» dep oqulidu."]],"巠":[["巠山历史悠久，文化深厚。","جىڭ تېغى ئۇزۇن تارىخقا ۋە چوڭقۇر مەدەنىيەتكە ئىگە.","jing téghi uzun tarixqa we chongqur medeniyetke ige."]],"幠":[["幠是一种古代的布，多用于礼仪场合。","خۇ قەدىمكى زاماندىكى بىر خىل رەخت بولۇپ، كۆپىنچە ئەدەپ-ئەخلاق مۇراسىملىرىدا ئىشلىتىلىدۇ.","xu qedimki zamandiki bir xil rext bolup, köpinche edep-exlaq murasimlirida ishlitilidu."]],"懠":[["他表现出懠然的神情。","ئۇ غەزەپلەنگەن ھالەتتە كۆرۈندى.","u ghezeplengen halette köründi."]],"戠":[["这个字读作“戠”，不常见。","بۇ خەت «جى» دەپ ئوقۇلىدۇ، كۆپ ئۇچرىمايدۇ.","bu xet «ji» dep oqulidu, köp uchrimaydu."]],"摠":[["他摠着袖子，准备开始工作。","ئۇ يەڭلىرىنى تۈرۈپ، خىزمەتنى باشلاشقا تەييارلاندى.","u yenglirini türüp, xizmetni bashlashqa teyyarlandi."]],"櫠":[["櫠木适合制作家具。","دۇڭباق ياغىچى ئۆي جاھازىسى ياساشقا ماس كېلىدۇ.","dungbaq yaghichi öy jahazisi yasashqa mas kélidu."]],"樠":[["樠木的香气很浓郁。","بۇ ياغاچنىڭ پۇرىقى بەك كۈچلۈك.","bu yaghachning puriqi bek küchlük."]],"薠":[["薠草很适合用作装饰。","ئوتلار بېزەك سۈپىتىدە ئىشلىتىشكە ئىنتايىن ماس كېلىدۇ.","otlar bézek süpitide ishlitishke intayin mas kélidu."]],"菠":[["菠菜是常见的绿叶蔬菜。","كۈنچىقار يېشىل يوپۇرماقلىق كۆكتاتتۇر.","künchiqar yéshil yopurmaqliq köktattur."]],"踠":[["她踠着身子靠在墙上。","ئۇ بەدىنىنى بۈكۈپ تامغا يۆلەندى.","u bedinini büküp tamgha yölendi."]],"輠":[["这种輠车在古代用于运输货物。","بۇ خىل ھارۋا قەدىمكى زاماندا يۈك توشۇشقا ئىشلىتىلگەن.","bu xil harwa qedimki zamanda yük toshushqa ishlitilgen."]],"鉠":[["古代战场上曾使用过这种鉠钟。","قەدىمكى جەڭ مەيدانلىرىدا بۇ خىل قوڭغۇراق ئىشلىتىلگەن.","qedimki jeng meydanlirida bu xil qongghuraq ishlitilgen."]],"鯠":[["这种鯠鱼在沿海地区很常见。","بۇ خىل لەي بېلىقى دېڭىز بويى رايونلاردا ئىنتايىن كۆپ ئۇچرايدۇ.","bu xil ley béliqi déngiz boyi rayonlarda intayin köp uchraydu."]],"鬠":[["鬠发浓密，让他看起来更有气势。","قويۇق چاچلىرى ئۇنى تېخىمۇ ھەيۋەتلىك كۆرسىتىدۇ.","qoyuq chachliri uni téximu heywetlik körsitidu."]],"一个半":[["这个房间一个半小时就能打扫完。","بۇ ئۆينى بىر يېرىم سائەتتە تازىلاپ بولغىلى بولىدۇ.","bu öyni bir yérim saette tazilap bolghili bolidu."]],"一般而言":[["一般而言，这种情况很少发生。","ئادەتتە، بۇنداق ئەھۋال ئاز ئۇچرايدۇ.","adette, bundaq ehwal az uchraydu."]],"一言为定":[["我们一言为定，绝不反悔。","بىز بىر ئېغىز سۆز بىلەن كېلىشتۇق، ھەرگىز قايتمايمىز.","biz bir éghiz söz bilen kélishtuq, hergiz qaytmaymiz."]],"一点点":[["他一点点地改进着自己的方法。","ئۇ ئۇسۇلىنى ئاز-ئازدىن ياخشىلاۋاتىدۇ.","u usulini az-azdin yaxshilawatidu."]],"丁丁":[["丁丁的声音清脆悦耳，让人心情愉悦。","دىڭدىڭنىڭ ئاۋازى سۈزۈك ۋە يېقىملىق، كىشىنىڭ كۆڭلىنى خۇشال قىلىدۇ.","dingdingning awazi süzük we yéqimliq, kishining könglini xushal qilidu."]],"三柱门":[["三柱门是古代的一种城门。","سەنزۇمېن قەدىمكى زاماندىكى بىر خىل شەھەر دەرۋازىسى.","senzumén qedimki zamandiki bir xil sheher derwazisi."]],"三合土":[["三合土是一种传统建筑材料。","ئۈچ خىل ماتېرىيال قوشۇلغان توپا ئەنئەنىۋى قۇرۇلۇش ماتېرىيالى.","üch xil matériyal qoshulghan topa en'eniwi qurulush matériyali."]],"三合星":[["三合星是占星学中的一个概念。","ئۈچ يۇلتۇزلۇق ئاسترونومىيەدە بىر ئۇقۇم.","üch yultuzluq astronomiyede bir uqum."]],"三言两语":[["只需三言两语就能解决问题。","پەقەت ئۈچ ئېغىز سۆز بىلەنلا مەسىلىنى ھەل قىلغىلى بولىدۇ.","peqet üch éghiz söz bilenla mesilini hel qilghili bolidu."]],"三门县":[["三门县以丰富的海洋资源闻名。","سانمېن ناھىيىسى مول دېڭىز بايلىقلىرى بىلەن تونۇلغان.","sanmén nahiyisi mol déngiz bayliqliri bilen tonulghan."]],"不太好":[["今天的天气不太好，出门要注意保暖。","بۈگۈن ھاۋا ئانچە ياخشى ئەمەس، سىرتقا چىققاندا ئىسسىق ساقلىنىشقا دىققەت قىلىڭ.","bügün hawa anche yaxshi emes, sirtqa chiqqanda issiq saqlinishqa diqqet qiling."]],"不复":[["他已不复从前。","ئۇ ئەمدى ئىلگىرىكىدەك ئەمەس.","u emdi ilgirikidek emes."]],"不才":[["在下不才，难当此任。","مەن ئەھمىيەتسىز، بۇ ۋەزىپىنى ئۈستىگە ئالالمايمەن.","men ehmiyetsiz, bu wezipini üstige alalmaymen."]],"不舍":[["他对旧物始终不舍。","ئۇ كونا نەرسىلەرگە ئەزەلدىن كۆڭۈل باغلاپ كەلدى.","u kona nersilerge ezeldin köngül baghlap keldi."]],"且末遗址":[["且末遗址是重要的考古发现。","چەرچەن خارابىسى مۇھىم ئارخېئولوگىيەلىك بايقاش.","cherchen xarabisi muhim arxéologiyelik bayqash."]],"且说":[["且说那日，发生了一件大事。","شۇ كۈنى بىر چوڭ ئىش يۈز بەردى.","shu küni bir chong ish yüz berdi."]],"世世代代":[["世世代代守护这片土地。","ئەۋلادتىن-ئەۋلادقا بۇ زېمىننى قوغدايدۇ.","ewladtin-ewladqa bu zéminni qoghdaydu."]],"世家":[["他们家族是当地的世家大族。","ئۇلارنىڭ ئائىلىسى يەرلىكتىكى ئاتاقلىق زاتلار ئائىلىسى ئىدى.","ularning ailisi yerliktiki ataqliq zatlar ailisi idi."]],"世银":[["世银为发展中国家提供贷款支持。","دۇنيا بانكىسى تەرەققىي قىلىۋاتقان دۆلەتلەرگە قەرز ياردىمى بېرىدۇ.","dunya bankisi tereqqiy qiliwatqan döletlerge qerz yardimi béridu."]],"丢魂":[["他被吓得差点丢魂。","ئۇ قورققىنىدىن جان-جېنىدىن ئايرىلىپ قالاي دەپ قالدى.","u qorqqinidin jan-jénidin ayrilip qalay dep qaldi."]],"丘北县":[["丘北县以独特的民族风情闻名。","چيۇبېي ناھىيىسى ئۆزىگە خاس مىللىي ئۇسلۇبى بىلەن داڭلىق.","chyubéy nahiyisi özige xas milliy uslubi bilen dangliq."]],"中中":[["这次考试他考了中中成绩。","بۇ قېتىمقى ئىمتىھاندا ئۇ ئوتتۇراھال نەتىجە ئالدى.","bu qétimqi imtihanda u otturahal netije aldi."]],"中共中央组织部":[["中共中央组织部负责干部选拔任用。","جۇڭگو كوممۇنىستىك پارتىيەسى مەركىزىي كومىتېتى تەشكىلات بۆلۈمى كادىرلارنى تاللاش ۋە تەيىنلەشكە مەسئۇل.","junggo kommunistik partiyesi merkiziy komitéti teshkilat bölümi kadirlarni tallash we teyinleshke mes'ul."]],"中流砥柱":[["他是团队的中流砥柱。","ئۇ كوماندىنىڭ ئوتتۇرا تۈۋرۈكىدۇر.","u komandining ottura tüwrükidur."]],"丹方":[["丹方是传统中医的重要配方之一。","دانفاڭ ئەنئەنىۋى جۇڭگو تېبابىتىنىڭ مۇھىم رېتسېپتلىرىنىڭ بىرى.","danfang en'eniwi junggo tébabitining muhim rétséptlirining biri."]],"主麻":[["主麻是一种传统服饰。","جۇمە ئەنئەنىۋى كىيىم-كېچەك.","jume en'eniwi kiyim-kéchek."]],"久病":[["久病缠身，让他身心俱疲。","ئۇزۇن ۋاقىت كېسەلگە گىرىپتار بولۇش ئۇنى جىسمانىي ۋە روھىي جەھەتتىن ھالدىن تالايتتى.","uzun waqit késelge giriptar bolush uni jismaniy we rohiy jehettin haldin talaytti."]],"中西合并":[["中西合并带来新机遇。","جۇڭگو بىلەن غەربنى بىرلەشتۈرۈش يېڭى پۇرسەتلەرنى ئېلىپ كېلىدۇ.","junggo bilen gherbni birleshtürüsh yéngi pursetlerni élip kélidu."]],"中庭":[["中庭是传统住宅中的庭院空间。","ھويلا ئوتتۇرىسى ئەنئەنىۋى تۇرالغۇدىكى ھويلا بوشلۇقىدۇر.","hoyla otturisi en'eniwi turalghudiki hoyla boshluqidur."]],"事到今日":[["事到今日，只能这样了。","ئىش بۈگۈنگە كەلگەندە، پەقەت مۇشۇنداق قىلىش كېرەك.","ish bügünge kelgende, peqet mushundaq qilish kérek."]],"事必躬亲":[["他事必躬亲，从不推诿责任。","ئۇ ھەممە ئىشقا ئۆزى ئارىلىشىپ، مەسئۇلىيەتنى ھەرگىز باشقىلارغا ئارتىپ قويمايدۇ.","u hemme ishqa özi ariliship, mes'uliyetni hergiz bashqilargha artip qoymaydu."]],"二手房":[["我们买了一套价格实惠的二手房。","بىز باھاسى مۇۋاپىق بىر يۈرۈش ئىككىنچى قول ئۆي سېتىۋالدۇق.","biz bahasi muwapiq bir yürüsh ikkinchi qol öy sétiwalduq."]],"二鬼子":[["他被称为二鬼子。","ئۇ ئىككى خۇيزۇ دەپ ئاتىلىدۇ.","u ikki xuyzu dep atilidu."]],"二氧化钛":[["二氧化钛常用于防晒霜中。","تىتان دىئوكسىد كۈن قوغداش كىرىمىدە كۆپ ئىشلىتىلىدۇ.","titan dioksid kün qoghdash kirimide köp ishlitilidu."]],"五级士官":[["他是一名经验丰富的五级士官。","ئۇ تەجرىبىلىك بەشىنچى دەرىجىلىك سەرپىي.","u tejribilik beshinchi derijilik serpiy."]],"五劳七伤":[["五劳七伤是中医中常见的病症类型。","بەش ھالسىزلىق يەتتە زەخىم تىبابەتتە كۆپ ئۇچرايدىغان كېسەللىك تۈرى.","besh halsizliq yette zexim tibabette köp uchraydighan késellik türi."]],"五十步笑百步":[["五十步笑百步，比喻自己犯错却嘲笑他人。","ئەللىك قەدەم كۈلۈپ يۈز قەدەمگە كۈلۈش، ئۆزى خاتالىق قىلىپ باشقىلارنى مەسخىرە قىلىشنى تەمسىل قىلىدۇ.","ellik qedem külüp yüz qedemge külüsh, özi xataliq qilip bashqilarni mesxire qilishni temsil qilidu."]],"五更":[["古代把一夜分为五更。","قەدىمدە بىر كېچىنى بەش بۆلەككە ئايرىغان.","qedimde bir kéchini besh bölekke ayrighan."]],"交变电流":[["交变电流是交流电的基本形式。","ئالمىشىپ ئېقىدىغان توك ئالماشتۇرۇش توكىنىڭ ئاساسىي شەكلى.","almiship éqidighan tok almashturush tokining asasiy shekli."]],"交规":[["遵守交规是每位驾驶员的责任。","قاتناش قائىدىسىگە رىئايە قىلىش ھەر بىر شوپۇرنىڭ مەسئۇلىيىتى.","qatnash qaidisige riaye qilish her bir shopurning mes'uliyiti."]],"亹亹":[["亹亹形容众多，难以计数。","ۋېيۋېي كۆپلۈكنى تەسۋىرلەيدۇ، سانىنى ئېنىقلاش تەس.","wéywéy köplükni teswirleydu, sanini éniqlash tes."]],"京畿道":[["京畿道是韩国首尔周边的一个重要行政区域。","جىڭگىدو كورېيەنىڭ سېئۇل ئەتراپىدىكى مۇھىم مەمۇرىي رايون.","jinggido koréyening séul etrapidiki muhim memuriy rayon."]],"令兄":[["令兄在学术界很有名。","ئاكىڭىز ئىلمىي ساھەدە ناھايىتى داڭلىق.","akingiz ilmiy sahede nahayiti dangliq."]],"仙游县":[["仙游县以丰富的文化闻名。","شىيەنيۇ ناھىيىسى مول مەدەنىيىتى بىلەن داڭلىق.","shiyenyu nahiyisi mol medeniyiti bilen dangliq."]],"代代":[["这个传统代代相传，从未中断。","بۇ ئەنئەنە ئەۋلادتىن ئەۋلادقا داۋاملىشىپ، ھېچقاچان ئۈزۈلگەن ئەمەس.","bu en'ene ewladtin ewladqa dawamliship, héchqachan üzülgen emes."]],"代扣":[["公司会代扣部分工资作为税款。","شىركەت ئەمگەك ھەققىنىڭ بىر قىسمىنى باج سۈپىتىدە تۇتۇپ قالىدۇ.","shirket emgek heqqining bir qismini baj süpitide tutup qalidu."]],"仰屋兴叹":[["面对困境，他只能仰屋兴叹。","قىيىنچىلىققا دۇچ كەلگەندە، ئۇ پەقەت ئۆي ئىچىدە پەرەز قىلىپ ئولتۇرۇپ ئۇھ تارتىشتىن باشقا ئامالى يوق ئىدى.","qiyinchiliqqa duch kelgende, u peqet öy ichide perez qilip olturup uh tartishtin bashqa amali yoq idi."]],"佛媛":[["她是一位热爱佛媛文化的年轻女子。","ئۇ بۇددا مەدەنىيىتىگە قىزىقىدىغان بىر ياش ئايال.","u budda medeniyitige qiziqidighan bir yash ayal."]],"佛龛":[["寺庙里的佛龛十分庄严。","ئىبادەتخانىدىكى بۇددا ئورنى ناھايىتى تەنتەنىلىك.","ibadetxanidiki budda orni nahayiti tentenilik."]],"住院医师":[["住院医师负责指导实习医生的日常工作。","يېتىپ داۋالايدىغان دوختۇر ئەمەلىيەتچى دوختۇرلارنىڭ كۈندىلىك خىزمىتىگە يېتەكچىلىك قىلىشقا مەسئۇل.","yétip dawalaydighan doxtur emeliyetchi doxturlarning kündilik xizmitige yétekchilik qilishqa mes'ul."]],"佐科威":[["佐科威是印度尼西亚的现任总统。","جوكوۋى ئىندونېزىيەنىڭ ھازىرقى پرېزىدېنتى.","jokowi indonéziyening hazirqi prézidénti."]],"低首下心":[["低首下心，虚心接受批评。","باشىنى ئېگىپ، كۆڭلىنى تۆۋەن قىلىپ، تەنقىدنى خۇشاللىق بىلەن قوبۇل قىلدى.","bashini égip, könglini töwen qilip, tenqidni xushalliq bilen qobul qildi."]],"低龄化":[["低龄化趋势引发社会关注。","تۆۋەن ياشلىشىش يۈزلىنىشى جەمئىيەتنىڭ دىققىتىنى قوزغىدى.","töwen yashlishish yüzlinishi jem'iyetning diqqitini qozghidi."]],"但书":[["但书是古代的一种记录方式。","دەپتەر ئەسكى زاماندا خاتىرىلەش ئۇسۇلىنىڭ بىرى.","depter eski zamanda xatirilesh usulining biri."]],"俗套":[["这种表达方式太过俗套，缺乏新意。","بۇ ئىپادىلەش ئۇسۇلى بەك كونا ئۇسلۇبتا بولۇپ، يېڭىلىق يوق.","bu ipadilesh usuli bek kona uslubta bolup, yéngiliq yoq."]],"俗字":[["这些俗字在现代汉语中已较少使用。","بۇ خىل ئاممىۋى يېزىق ھازىرقى زامان خەنزۇ تىلىدا ئاز ئىشلىتىلىدۇ.","bu xil ammiwi yéziq hazirqi zaman xenzu tilida az ishlitilidu."]],"佳音":[["收到他的佳音，我感到非常高兴。","ئۇنىڭ خۇش خەۋىرىنى ئاڭلاپ، مەن ئىنتايىن خۇشال بولدۇم.","uning xush xewirini anglap, men intayin xushal boldum."]],"俑坑":[["考古学家在地下发现了大型俑坑。","ئارخېئولوگلار يەر ئاستىدىن چوڭ تىپتىكى يىنپۇڭلارنى بايقىدى.","arxéologlar yer astidin chong tiptiki yinpunglarni bayqidi."]],"保护性":[["这款手机具有出色的防水保护性。","بۇ تېلېفون ئالاھىدە سۇدىن قوغداش خۇسۇسىيىتىگە ئىگە.","bu téléfon alahide sudin qoghdash xususiyitige ige."]],"修订历史":[["这个文档的修订历史非常详细。","بۇ ھۆججەتنىڭ تۈزىتىش تارىخى ئىنتايىن تەپسىلىي.","bu höjjetning tüzitish tarixi intayin tepsiliy."]],"信条":[["他的信条是诚实守信。","ئۇنىڭ ئېتىقاد پرىنسىپى سەمىمىي ۋە ۋەدىگە ۋاپادار بولۇش.","uning étiqad prinsipi semimiy we wedige wapadar bolush."]],"倔头":[["倔头倔脑的孩子最难管教。","قەيسەر بالىلارنى تەربىيىلەش ئەڭ قىيىن.","qeyser balilarni terbiyilesh eng qiyin."]],"幸存":[["幸存者讲述了灾难的经历。","ئامان قالغۇچىلار ئاپەت باشتىن كەچۈرگەنلىرىنى سۆزلەپ بەردى.","aman qalghuchilar apet bashtin kechürgenlirini sözlep berdi."]],"候车亭":[["候车亭下避雨方便。","كۈتۈش سايىۋىنى ئاستىدا يامغۇردىن پاناھلىنىش قولايلىق.","kütüsh sayiwini astida yamghurdin panahlinish qolayliq."]],"个把":[["有个把问题需要解决。","ھەل قىلىشقا تېگىشلىك بىر-ئىككى مەسىلە بار.","hel qilishqa tégishlik bir-ikki mesile bar."]],"倒苦水":[["她向朋友倒苦水。","ئۇ دوستىغا ئاچچىق-زەھىرىنى تۆكتى.","u dostigha achchiq-zehirini tökti."]],"做空":[["他尝试做空头交易。","ئۇ بوش سېتىش-سېتىۋېلىش قىلىشنى سىناپ باقتى.","u bosh sétish-sétiwélish qilishni sinap baqti."]],"偶蹄目":[["偶蹄目包括许多常见的哺乳动物。","جۈپ تۇياقلىقلار تۈركۈمى كۆپ ئۇچرايدىغان سۈت ئەمگۈچى ھايۋانلارنى ئۆز ئىچىگە ئالىدۇ.","jüp tuyaqliqlar türkümi köp uchraydighan süt emgüchi haywanlarni öz ichige alidu."]],"偷偷摸摸":[["他们偷偷摸摸地完成了计划。","ئۇلار پىلاننى ئوغرىلىقچە ئەمەلگە ئاشۇردى.","ular pilanni oghriliqche emelge ashurdi."]],"做为":[["做为朋友，你要多包容。","دوست بولۇش سۈپىتىڭىز بىلەن، سىز كۆپرەك كەڭ قورساق بولۇشىڭىز كېرەك.","dost bolush süpitingiz bilen, siz köprek keng qorsaq bolushingiz kérek."]],"备而不用":[["这些方案备而不用，以防万一。","بۇ پىلانلار ئېھتىيات ئۈچۈن تەييارلىنىپ، ئىشلىتىلمەيدۇ.","bu pilanlar éhtiyat üchün teyyarlinip, ishlitilmeydu."]],"传开":[["谣言很快在人群中传开。","مىش-مىش پاراڭلار ئادەملەر ئارىسىدا تېز تارقالدى.","mish-mish paranglar ademler arisida téz tarqaldi."]],"充畅":[["河水充畅，奔流不息。","دەريا سۈيى مول، ئېقىپ توختىمايدۇ.","derya süyi mol, éqip toxtimaydu."]],"先决条件":[["先决条件已完全满足。","ئالدىنقى شەرتلەر تولۇق ھازىرلاندى.","aldinqi shertler toluq hazirlandi."]],"克维拉":[["克维拉是当地一种特色饮品。","كرىۋېتسا بىر يەرلىك ئالاھىدە ئىچىملىكتۇر.","kriwétsa bir yerlik alahide ichimliktur."]],"全球气候":[["全球气候正在发生显著变化。","دۇنياۋى ئىقلىم كۆرۈنەرلىك ئۆزگىرىۋاتىدۇ.","dunyawi iqlim körünerlik özgiriwatidu."]],"两口儿":[["他们两口儿很恩爱。","ئۇلار ئىككىيلەن ناھايىتى ئىناق.","ular ikkiylen nahayiti inaq."]],"全身心":[["他全身心投入到工作中，毫无分心。","ئۇ پۈتۈن ۋۇجۇدى بىلەن خىزمەتكە ئاتلىنىپ، زىرەدىن خالىي بولدى.","u pütün wujudi bilen xizmetke atlinip, ziredin xaliy boldi."]],"两生类":[["两生类生物能够适应多种环境。","ئىككى ياشاش تۈرىدىكى جانلىقلار تۈرلۈك مۇھىتقا ماسلىشالايدۇ.","ikki yashash türidiki janliqlar türlük muhitqa maslishalaydu."]],"内内":[["内内是孩子们最喜欢的玩具。","ئىچكى كىيىم بالىلارنىڭ ئەڭ ياخشى كۆرىدىغان ئويۇنچۇقى.","ichki kiyim balilarning eng yaxshi köridighan oyunchuqi."]],"八步区":[["八步区是中国广西壮族自治区的一个区。","سەككىز ئەدەم رايونى جۇڭگو گۇاڭشى جۇاڭزۇ ئاپتونوم رايونىدىكى بىر رايون.","sekkiz edem rayoni junggo guangshi juangzu aptonom rayonidiki bir rayon."]],"公敌":[["他被视为整个行业的公敌。","ئۇ پۈتۈن ساھەنىڭ ئاممىۋى دۈشمىنى دەپ قارىلىدۇ.","u pütün sahening ammiwi düshmini dep qarilidu."]],"八月份":[["八月份是夏季的最后一个月。","سەككىزىنچى ئاي يازنىڭ ئاخىرقى ئېيى.","sekkizinchi ay yazning axirqi éyi."]],"冉冉":[["太阳冉冉升起。","قۇياش ئاستا-ئاستا كۆتۈرۈلمەكتە.","quyash asta-asta kötürülmekte."]],"公司会议":[["公司会议讨论了季度计划。","شىركەت يىغىنىدا پەسىللىك پىلان مۇزاكىرە قىلىندى.","shirket yighinida pesillik pilan muzakire qilindi."]],"冒冒失失":[["他冒冒失失地闯了祸。","ئۇ ئالدىراپ بىر ئاپەت كەلتۈرۈپ قويدى.","u aldirap bir apet keltürüp qoydi."]],"冷冷":[["天气冷冷，让人打寒颤。","ھاۋا سوغۇق، كىشىلەرنى تىترىتىدۇ.","hawa soghuq, kishilerni titritidu."]],"刑网":[["刑网覆盖所有罪行。","جازا تورى بارلىق جىنايەتلەرنى قاپلايدۇ.","jaza tori barliq jinayetlerni qaplaydu."]],"列夫·托尔斯泰":[["列夫·托尔斯泰是俄国作家。","لېف تولستوي رۇسىيەلىك يازغۇچى.","léf tolstoy rusiyelik yazghuchi."]],"列宁格勒":[["列宁格勒曾是苏联的重要工业城市。","لېنىنگراد ئىلگىرى سوۋېت ئىتتىپاقىنىڭ مۇھىم سانائەت شەھىرى ئىدى.","léningrad ilgiri sowét ittipaqining muhim sanaet shehiri idi."]],"列弗":[["列弗是俄罗斯著名作家陀思妥耶夫斯基的笔名。","لېف رۇسىيەلىك مەشھۇر يازغۇچى دوستويېۋسكىينىڭ تەخەللۇسى.","léf rusiyelik meshhur yazghuchi dostoyéwskiyning texellusi."]],"判处":[["法院判处他无期徒刑。","سوت مەھكىمىسى ئۇنى ئۆمۈر بويى قاماق جازاسىغا ھۆكۈم قىلدى.","sot mehkimisi uni ömür boyi qamaq jazasigha höküm qildi."]],"到齐":[["所有人员到齐后开始会议。","بارلىق خادىملار يىغىلغاندىن كېيىن يىغىن باشلىنىدۇ.","barliq xadimlar yighilghandin kéyin yighin bashlinidu."]],"副标题":[["文章的副标题补充了主题内容。","ماقالىنىڭ تارماق تېمىسى ئاساسىي تېمىنى تولۇقلىدى.","maqalining tarmaq témisi asasiy témini toluqlidi."]],"剧照":[["剧照展示了演员的精彩瞬间。","تېياتىر سۈرىتى ئارتىسلارنىڭ ئاجايىپ لەھزىلىرىنى نامايان قىلدى.","téyatir süriti artislarning ajayip lehzilirini namayan qildi."]],"创痛":[["失败带来的创痛令人难忘。","مەغلۇبىيەت ئېلىپ كەلگەن يارا ئۇنتۇلغۇسىز.","meghlubiyet élip kelgen yara untulghusiz."]],"刘宋时代":[["刘宋时代是中国历史上的重要时期。","لىۇ سۇڭ دەۋرى جۇڭگو تارىخىدىكى مۇھىم بىر دەۋر.","liu sung dewri junggo tarixidiki muhim bir dewr."]],"刘禹锡":[["刘禹锡是唐代著名的诗人和政治家。","لىۇ يۈشى تاڭ سۇلالىسى دەۋرىدىكى مەشھۇر شائىر ۋە سىياسەتچى.","liu yüshi tang sulalisi dewridiki meshhur shair we siyasetchi."]],"功不可没":[["他的功不可没，值得称赞。","ئۇنىڭ تۆھپىسىنى ئىنكار قىلغىلى بولمايدۇ، تەستىقلىشقا ئەرزىيدۇ.","uning töhpisini inkar qilghili bolmaydu, testiqlishqa erziydu."]],"加工贸易":[["加工贸易是重要的经济模式。","بىر تەرەپ قىلىش سودىسى مۇھىم ئىقتىسادىي ئەندىزە.","bir terep qilish sodisi muhim iqtisadiy endize."]],"加密货币":[["加密货币的价格近期波动很大。","شىفىرلانغان پۇلنىڭ باھاسى يېقىندا ناھايىتى تەۋرىنىشلىك بولدى.","shifirlanghan pulning bahasi yéqinda nahayiti tewrinishlik boldi."]],"胜不骄，败不馁":[["胜不骄，败不馁是成功的关键。","غەلىبە قازانغاندا مەغرۇرلانماسلىق، مەغلۇپ بولغاندا رۇھى چۈشمەسلىك مۇۋەپپەقىيەتنىڭ ئاچقۇچى.","ghelibe qazanghanda meghrurlanmasliq, meghlup bolghanda ruhi chüshmeslik muweppeqiyetning achquchi."]],"努力以赴":[["他努力以赴，不负众望。","ئۇ تىرىشچانلىق كۆرسىتىپ، كۆپچىلىكنىڭ ئۈمىدىنى ئاقلىدى.","u tirishchanliq körsitip, köpchilikning ümidini aqlidi."]],"勾连":[["这些勾连行为被彻底揭露。","بۇ چاتاقلىشىش قىلمىشلىرى پۈتۈنلەي ئاشكارىلاندى.","bu chataqlishish qilmishliri pütünley ashkarilandi."]],"包包":[["她背着一个漂亮的包包。","ئۇ چىرايلىق بىر سومكا ئېسىپ يۈرۈپتۇ.","u chirayliq bir somka ésip yürüptu."]],"勉力而为":[["他勉力而为，总算成功。","ئۇ بار كۈچى بىلەن تىرىشتى، ئاخىرى مۇۋەپپەقىيەت قازاندى.","u bar küchi bilen tirishti, axiri muweppeqiyet qazandi."]],"勉勉强强":[["他勉勉强强通过了考试。","ئۇ جاپا-مۇشەققەت بىلەن ئىمتىھاندىن ئۆتتى.","u japa-musheqqet bilen imtihandin ötti."]],"勤勤恳恳":[["老师勤勤恳恳，诲人不倦。","ئوقۇتقۇچى ئىخلاسمەنلىك بىلەن ئوقۇتۇپ، ھېچ زېرىكمەي تەلىم بېرىدۇ.","oqutquchi ixlasmenlik bilen oqutup, héch zérikmey telim béridu."]],"化学纤维":[["这种衣服由化学纤维制成。","بۇ خىل كىيىم خىمىيىلىك تالادىن ياسالغان.","bu xil kiyim ximiyilik taladin yasalghan."]],"北林":[["北林风景优美。","شىمالىي لىننىڭ مەنزىرىسى گۈزەل.","shimaliy linning menzirisi güzel."]],"半个":[["我吃了半个苹果就饱了。","مەن يېرىم ئالما يېسىلا تويۇپ قالدىم.","men yérim alma yésila toyup qaldim."]],"半半拉拉":[["他做事总是半半拉拉，不彻底。","ئۇ ئىش قىلغاندا ھەمىشە يېرىم-يېرىم قىلىپ، ئاخىرلاشتۇرمايدۇ.","u ish qilghanda hemishe yérim-yérim qilip, axirlashturmaydu."]],"南岗":[["南岗是哈尔滨市的一个老城区。","نەنگاڭ خاربىن شەھىرىنىڭ بىر كونا شەھەر رايونى.","nengang xarbin shehirining bir kona sheher rayoni."]],"北斗":[["北斗是中国古代重要的星象体系。","بېيدۇ جۇڭگو قەدىمكى زامانىدىكى مۇھىم يۇلتۇز ئوبيېكتى سىستېمىسىدۇر.","béydu junggo qedimki zamanidiki muhim yultuz obyékti sistémisidur."]],"卜昼卜夜":[["他卜昼卜夜，废寝忘食。","ئۇ كېچە-كۈندۈز پال ئېلىش بىلەن ئۇيقۇ ۋە تاماقنى ئۇنتۇپ قالدى.","u kéche-kündüz pal élish bilen uyqu we tamaqni untup qaldi."]],"印子":[["这个印子清晰可见。","بۇ تامغا ئېنىق كۆرۈنۈپ تۇرىدۇ.","bu tamgha éniq körünüp turidu."]],"卡利卡特":[["卡利卡特是历史上的贸易中心。","كالىكۇت تارىختا سودا مەركىزى بولغان.","kalikut tarixta soda merkizi bolghan."]],"厄立特里亚":[["厄立特里亚独立了。","ئېرىترېيا مۇستەقىل بولدى.","éritréya musteqil boldi."]],"参选率":[["参选率反映了民众的参与意愿。","سايلىمغا قاتنىشىش نىسبىتى خەلقنىڭ قاتنىشىش ئارزۇسىنى ئەكس ئەتتۈرىدۇ.","saylimgha qatnishish nisbiti xelqning qatnishish arzusini eks ettüridu."]],"参院":[["参院负责立法和审议法案。","سېنات قانۇن چىقىرىش ۋە قانۇن تەكلىپىنى كۆزدىن كەچۈرۈشكە مەسئۇل.","sénat qanun chiqirish we qanun teklipini közdin kechürüshke mes'ul."]],"原班人马":[["原班人马再次合作完成项目。","ئەسلىي گۇرۇپپا ئەزالىرى قايتا ھەمكارلىشىپ تۈرنى تاماملىدى.","esliy guruppa ezaliri qayta hemkarliship türni tamamlidi."]],"原生":[["这种植物属于原生物种。","بۇ خىل ئۆسۈملۈك ئەسلىي تۈرگە تەۋە.","bu xil ösümlük esliy türge tewe."]],"去死":[["别去死，还有希望！","ئۆلۈشكە ئالدىرىما، ئۈمىد بار!","ölüshke aldirima, ümid bar!"]],"卵磷脂":[["卵磷脂对大脑发育很重要。","تۇخۇم سېرىق ماددىسى مېڭە تەرەققىياتى ئۈچۈن ئىنتايىن مۇھىم.","tuxum sériq maddisi ménge tereqqiyati üchün intayin muhim."]],"受刑人":[["受刑人要求得到公正对待。","جازالانغۇچى ئادىل مۇئامىلە قىلىنىشىنى تەلەپ قىلدى.","jazalanghuchi adil muamile qilinishini telep qildi."]],"古根罕":[["古根罕是著名的艺术收藏家。","گۇگېنھېيم مەشھۇر سەنئەت توپلىغۇچىدۇر.","gugénhéym meshhur sen'et toplighuchidur."]],"台北捷运":[["我坐台北捷运上班。","مەن تەيبېي مېتروسىدا ئىشخانىغا بارىمەن.","men teybéy métrosida ishxanigha barimen."]],"反空降":[["反空降战术在现代战争中罕见。","ھاۋادىن قونۇشقا قارشى تاكتىكا زامانىۋى ئۇرۇشتا ئاز ئۇچرايدۇ.","hawadin qonushqa qarshi taktika zamaniwi urushta az uchraydu."]],"反刍":[["牛会反刍，把食物重新咀嚼。","كالىلار كەۋسەيدۇ، يېمەكلىكنى قايتا چاينەيدۇ.","kalilar kewseydu, yémeklikni qayta chayneydu."]],"史氏蝗莺":[["史氏蝗莺是一种分布于亚洲的鸟类。","شى ئۇرۇقى چىكەتكىسى ئاسىيادا تارقالغان بىر خىل قۇش.","shi uruqi chiketkisi asiyada tarqalghan bir xil qush."]],"吁吁":[["马儿“吁吁”地叫着，停下脚步。","ئات «ھىيھىي» دەپ كىشىنىپ، پۇتىنى توختاتتى.","at «hiyhiy» dep kishinip, putini toxtatti."]],"吃布":[["他不小心吃布了。","ئۇ سەۋەنسىزلىكتىن خاتالىق ئۆتكۈزدى.","u sewensizliktin xataliq ötküzdi."]],"吃不上":[["他连饭都吃不上，生活十分艰难。","ئۇ تاماقمۇ يېيەلمەيدۇ، تۇرمۇشى بەك قىيىن.","u tamaqmu yéyelmeydu, turmushi bek qiyin."]],"吃吃":[["我们边聊边吃吃零食。","بىز پاراڭلىشىپ ئولتۇرۇپ يېمەك-ئىچمەك يەيمىز.","biz parangliship olturup yémek-ichmek yeymiz."]],"合用":[["这个工具非常合用。","بۇ قورال ئىنتايىن پايدىلىق.","bu qoral intayin paydiliq."]],"名位":[["他凭借实力获得了名位。","ئۇ كۈچ-قۇدرىتىگە تايىنىپ نام-مەنسەپكە ئېرىشتى.","u küch-qudritige tayinip nam-mensepke érishti."]],"吞精":[["他吞精后感到虚弱不堪。","ئۇ مەنىنى يۇتقاندىن كېيىن ئاجىزلىق ھېس قىلدى.","u menini yutqandin kéyin ajizliq hés qildi."]],"吠陀":[["《吠陀》是古代印度经典。","ۋېدا قەدىمكى ھىندىستاننىڭ كلاسسىك ئەسىرى.","wéda qedimki hindistanning klassik esiri."]],"吧唧":[["他吧唧着嘴吃零食。","ئۇ لەۋلىرىنى چاپىلدىتىپ يېمەكلىك يەۋاتىدۇ.","u lewlirini chapilditip yémeklik yewatidu."]],"含含糊糊":[["他说话含含糊糊。","ئۇ سۆزلىگەندە ئېنىق ئەمەس.","u sözligende éniq emes."]],"合成器":[["音乐合成器能创造新声音。","مۇزىكا سىنتېزاتورى يېڭى ئاۋازلارنى يارىتالايدۇ.","muzika sintézatori yéngi awazlarni yaritalaydu."]],"吭吭":[["他吭吭地咳嗽了几声。","ئۇ پەس ئاۋاز بىلەن بىر قانچە قېتىم يۆتەلدى.","u pes awaz bilen bir qanche qétim yöteldi."]],"吱吱嘎嘎":[["门发出吱吱嘎嘎的声响。","ئىشىك غىچىرلاپ ئاۋاز چىقاردى.","ishik ghichirlap awaz chiqardi."]],"吴市吹箫":[["吴市吹箫是古代文人雅事。","ۋۇشىدا شياۋ ئۇرۇش قەدىمكى زامان ئەدىبلىرىنىڭ نەپىس ئىشى.","wushida shyaw urush qedimki zaman ediblirining nepis ishi."]],"吵吵":[["他整天吵吵个不停。","ئۇ كۈن بويى ۋاراڭ-چۇرۇڭ قىلىپ توختىمايدۇ.","u kün boyi warang-churung qilip toxtimaydu."]],"呫呫":[["他呫呫地笑。","ئۇ چىشلىرىنى چىشلەپ كۈلۈمسىرىدى.","u chishlirini chishlep külümsiridi."]],"咖啡屋":[["那家咖啡屋生意很红火。","ئۇ قەھۋەخانىنىڭ تىجارىتى ئىنتايىن قىزغىن.","u qehwexanining tijariti intayin qizghin."]],"哈姆雷特":[["哈姆雷特是莎士比亚的经典戏剧。","خاملىت شېكسپىرنىڭ كلاسسىك تىياتىرىدۇر.","xamlit shékspirning klassik tiyatiridur."]],"哈德斯":[["哈德斯是哈得斯的别称。","خادىس خادىسنىڭ باشقا ئاتىلىشىدۇر.","xadis xadisning bashqa atilishidur."]],"哇哇":[["宝宝哇哇地哭个不停。","بوۋاق ۋاڭ-ۋاڭ قىلىپ يىغلاۋەردى.","bowaq wang-wang qilip yighlawerdi."]],"哈博罗内":[["哈博罗内是博茨瓦纳的首都。","ھابورونې بوتسۋانانىڭ پايتەختى.","haboroné botswananing paytexti."]],"咕咾肉":[["咕咾肉是一道经典的粤菜。","گۇلاۋرۇ گۇاڭدۇڭ تائاملىرىنىڭ كلاسسىك بىر تۈرى.","gulawru guangdung taamlirining klassik bir türi."]],"哀鸿遍野":[["战争过后，哀鸿遍野，一片凄凉。","ئۇرۇشتىن كېيىن، ئەلەملىك قۇشلار ھەممە يەردە، بىر مەنزىرە خارابىلىك ئىدى.","urushtin kéyin, elemlik qushlar hemme yerde, bir menzire xarabilik idi."]],"唉唉":[["他唉唉两声，表示无奈和沮丧。","ئۇ ئىككى قېتىم «ئەھە» دەپ، ناچارلىق ۋە ئۈمىدسىزلىكىنى بىلدۈردى.","u ikki qétim «ehe» dep, nacharliq we ümidsizlikini bildürdi."]],"唐氏儿":[["唐氏儿需要特别的护理。","تاڭ ئەپەندى بالىسىغا ئالاھىدە كۈتۈنۈش كېرەك.","tang ependi balisigha alahide kütünüsh kérek."]],"呵呵":[["他笑着说：“呵呵，真有趣！","ئۇ كۈلۈپ: «خېخې، بەك قىزىقارلىق!» دېدى.","u külüp: «xéxé, bek qiziqarliq!» dédi."]],"呷呷":[["小猫发出呷呷的叫声。","كىچىك مۈشۈك «جاڭ-جاڭ» دېگەن ئاۋاز چىقاردى.","kichik müshük «jang-jang» dégen awaz chiqardi."]],"咧咧":[["他咧咧地笑着，很开心。","ئۇ ھىڭشىيىپ كۈلۈپ، بەك خۇشال بولدى.","u hingshiyip külüp, bek xushal boldi."]],"咯咯":[["鸡咯咯地叫着。","توخۇ گاق-گاق قىلىپ چاقىردى.","toxu gaq-gaq qilip chaqirdi."]],"唧唧":[["小鸟发出唧唧的叫声。","كىچىك قۇش جىجىلاپ سايرايدۇ.","kichik qush jijilap sayraydu."]],"唧唧嘎嘎":[["鸭子们唧唧嘎嘎地叫着。","ئۆردەكلەر جىجىڭ-جىجىڭ قىلىپ باقىرايدۇ.","ördekler jijing-jijing qilip baqiraydu."]],"商品价值":[["商品价值由供需决定。","مال قىممىتى تەمىنلەش ۋە تەلەپ بىلەن بەلگىلىنىدۇ.","mal qimmiti teminlesh we telep bilen belgilinidu."]],"商学":[["商学课程教授企业运营的基础知识。","سودا ئىلمى دەرسلىرى كارخانا باشقۇرۇشنىڭ ئاساسىي بىلىملىرىنى ئۆگىتىدۇ.","soda ilmi dersliri karxana bashqurushning asasiy bilimlirini ögitidu."]],"哐哐啷啷":[["汽车在坑洼路上哐哐啷啷地响。","ماشىنا چۇقۇر-چۇقۇر يولدا گۈرۈلدەپ ماڭدى.","mashina chuqur-chuqur yolda gürüldep mangdi."]],"唯唯诺诺":[["他说话总是唯唯诺诺。","ئۇ سۆزلىگەندە ھەمىشە پەقەت خۇشامەت قىلىدۇ.","u sözligende hemishe peqet xushamet qilidu."]],"哩哩啰啰":[["他说话总是哩哩啰啰，让人听不清重点。","ئۇ سۆزلىگەندە ھەمىشە لىلىلارلاپ، ئاڭلىغۇچىغا مۇھىم نۇقتىنى ئېنىق ئاڭلىتالمايدۇ.","u sözligende hemishe lililarlap, anglighuchigha muhim nuqtini éniq anglitalmaydu."]],"哭哭啼啼":[["她哭哭啼啼地诉说着自己的委屈。","ئۇ يىغلاپ-يىغلاپ ئۆزىنىڭ ئەجەللىك ئازابىنى ئېيتىپ بەردى.","u yighlap-yighlap özining ejellik azabini éytip berdi."]],"喀拉汗王朝":[["喀拉汗王朝统治了中亚地区数百年。","قاراخانىلار سۇلالىسى ئوتتۇرا ئاسىيا رايونىنى نەچچە يۈز يىل ئىدارە قىلدى.","qaraxanilar sulalisi ottura asiya rayonini nechche yüz yil idare qildi."]],"喀麦隆":[["喀麦隆是非洲中西部的一个国家。","كامېرۇن ئافرىقىنىڭ غەربىي ئوتتۇرا قىسمىدىكى بىر دۆلەتتۇر.","kamérun afriqining gherbiy ottura qismidiki bir dölettur."]],"喁喁":[["两人喁喁私语，情意绵绵。","ئىككىيلەن پىچىرلاپ سۆزلەشتى، مېھىر-مۇھەببەتلىك ئىدى.","ikkiylen pichirlap sözleshti, méhir-muhebbetlik idi."]],"喜饼":[["喜饼是婚礼上常见的传统点心。","توي پېتىرى توي مۇراسىمىدا كۆپ ئۇچرايدىغان ئەنئەنىۋى تائام.","toy pétiri toy murasimida köp uchraydighan en'eniwi taam."]],"喑哑":[["他的声音因过度喊叫而喑哑。","ئۇنىڭ ئاۋازى ھەددىدىن زىيادە ۋارقىرىغانلىقتىن بوغۇقلىشىپ قالدى.","uning awazi heddidin ziyade warqirighanliqtin boghuqliship qaldi."]],"乔布斯":[["乔布斯是苹果公司创始人。","جوبس ئالما شىركىتىنىڭ قۇرغۇچىسىدۇر.","jobs alma shirkitining qurghuchisidur."]],"单单":[["单单这一项任务就让他忙得不可开交。","پەقەت مۇشۇ بىر ۋەزىپىلا ئۇنى بەك ئالدىراتتى.","peqet mushu bir wezipila uni bek aldiratti."]],"嘉义":[["嘉义是台湾南部的重要城市。","جيا يى تەيۋەننىڭ جەنۇبىدىكى مۇھىم شەھەر.","jya yi teywenning jenubidiki muhim sheher."]],"哕哕":[["他哕哕地咳嗽个不停。","ئۇ يۆتەل-يۆتەل يۆتەلىپ توختىمىدى.","u yötel-yötel yötelip toxtimidi."]],"哗哗":[["他哗哗地翻着书页。","ئۇ شىلدىرلىتىپ بەتلەرنى ئاختۇردى.","u shildirlitip betlerni axturdi."]],"叽叽嘎嘎":[["小鸡们叽叽嘎嘎地叫着。","چۆجىلەر چىقىرلاپ چاقىرماقتا.","chöjiler chiqirlap chaqirmaqta."]],"嘻嘻":[["她嘻嘻地笑着。","ئۇ ھىپىلداپ كۈلۈۋاتىدۇ.","u hipildap külüwatidu."]],"严严实实":[["窗户被布严严实实地遮住了。","دېرىزە رەخت بىلەن مۇستەھكەم توسۇلغان.","dérize rext bilen mustehkem tosulghan."]],"严斥":[["老师严斥了学生的错误行为。","ئوقۇتقۇچى ئوقۇغۇچىنىڭ خاتا قىلمىشىنى قاتتىق تەنقىد قىلدى.","oqutquchi oqughuchining xata qilmishini qattiq tenqid qildi."]],"严查":[["警方对案件进行了严查细究。","ساقچىلار دېلوغا قاتتىق تەكشۈرۈش ۋە ئىنچىكە تەھلىل ئېلىپ باردى.","saqchilar délogha qattiq tekshürüsh we inchike tehlil élip bardi."]],"喳喳":[["小鸟喳喳叫个不停。","كىچىك قۇشلار توختىماي چىرىلدىلايدۇ.","kichik qushlar toxtimay chirildilaydu."]],"四大皆空":[["四大皆空是佛教哲学中的核心概念。","تۆت چوڭنىڭ ھەممىسى قۇرۇق بولۇش بۇددا پەلسەپەسىدىكى يادرولۇق ئۇقۇمدۇر.","töt chongning hemmisi quruq bolush budda pelsepesidiki yadroluq uqumdur."]],"四两拨千斤":[["他用四两拨千斤的功夫化解了对手的攻击。","ئۇ تۆت تەڭگىگە مىڭنى يۆتكەيدىغان ماھارىتى بىلەن رەقىبىنىڭ ھۇجۇمىنى يوق قىلدى.","u töt tenggige mingni yötkeydighan mahariti bilen reqibining hujumini yoq qildi."]],"四分之一":[["四分之一的概率意味着很小的可能性。","تۆتتىن بىر ئېھتىماللىق ئىنتايىن كىچىك پۇرسەتنى كۆرسىتىدۇ.","töttin bir éhtimalliq intayin kichik pursetni körsitidu."]],"四平八稳":[["他的性格四平八稳，让人十分放心。","ئۇنىڭ مىجەزى پاكىز مۇقىم، كىشىنى ئىنتايىن خاتىرجەم قىلىدۇ.","uning mijezi pakiz muqim, kishini intayin xatirjem qilidu."]],"回放":[["比赛录像支持无限次回放功能。","مۇسابىقە خاتىرىسى چەكسىز قېتىم قايتا قويۇش ئىقتىدارىنى قوللايدۇ.","musabiqe xatirisi cheksiz qétim qayta qoyush iqtidarini qollaydu."]],"囡囡":[["囡囡是父母对女儿的昵称。","نۈننۈن ئاتا-ئانىنىڭ قىزىغا قويغان ئەركە تەخەللۇسىدۇر.","nünnün ata-anining qizigha qoyghan erke texellusidur."]],"圈圈叉叉":[["圈圈叉叉的图案很复杂。","چەمبىرەك ۋە ئىككى خەتلىك نەقىش ناھايىتى مۇرەككەپ.","chembirek we ikki xetlik neqish nahayiti murekkep."]],"圈圈点点":[["圈圈点点装饰了整幅画。","چەمبىرەك ۋە نۇقتىلار پۈتۈن رەسىمنى بېزىدى.","chembirek we nuqtilar pütün resimni bézidi."]],"国民议会":[["国民议会是立法的重要机构。","مىللىي پارلامېنت قانۇن چىقىرىشنىڭ مۇھىم ئورگىنى.","milliy parlamént qanun chiqirishning muhim orgini."]],"国际法庭":[["国际法庭处理国家间的重大法律争端。","خەلقئارا سوت دۆلەتلەر ئارىسىدىكى مۇھىم قانۇنىي تالاش-تارتىشلارنى بىر تەرەپ قىلىدۇ.","xelq'ara sot döletler arisidiki muhim qanuniy talash-tartishlarni bir terep qilidu."]],"国际跳棋":[["国际跳棋深受玩家喜爱。","خەلقئارا دامكا ئويۇنى ئوينىغۇچىلار تەرىپىدىن ئىنتايىن ياخشى كۆرۈلىدۇ.","xelq'ara damka oyuni oynighuchilar teripidin intayin yaxshi körülidu."]],"圆润":[["她的笑容圆润而温暖。","ئۇنىڭ كۈلۈمسىرىشى يۇمىلاق ۋە ئىللىق.","uning külümsirishi yumilaq we illiq."]],"圆面饼":[["圆面饼口感酥脆。","يۇمىلاق ناننىڭ تەملىكى غۇۋا.","yumilaq nanning temliki ghuwa."]],"国际公认":[["这项成果得到了国际公认。","بۇ نەتىجە خەلقئارا جەھەتتىن ئېتىراپ قىلىندى.","bu netije xelq'ara jehettin étirap qilindi."]],"国际刑警组织":[["国际刑警组织打击跨国犯罪。","خەلقئارا جىنايى ساقچى تەشكىلاتى دۆلەتلەر ئارا جىنايەتكە زەربە بېرىدۇ.","xelq'ara jinayi saqchi teshkilati döletler ara jinayetke zerbe béridu."]],"土卫二":[["土卫二可能存在液态水，是探索目标。","توپا ھەمراھى ئىككىدە سۇيۇق سۇ مەۋجۇت بولۇشى مۇمكىن، ئۇ تەكشۈرۈش نىشانى.","topa hemrahi ikkide suyuq su mewjut bolushi mumkin, u tekshürüsh nishani."]],"国都":[["国都是国家的首都。","دۆلەت پايتەختى دۆلەتنىڭ پايتەختى.","dölet paytexti döletning paytexti."]],"国徽":[["国徽象征国家的尊严。","دۆلەت گېربى دۆلەتنىڭ ئىززەت-ھۆرمىتىنى سىمۋوللايدۇ.","dölet gérbi döletning izzet-hörmitini simwollaydu."]],"地地道道":[["他地地道道是个好人。","ئۇ پۈتۈنلەي ياخشى ئادەم.","u pütünley yaxshi adem."]],"垣衣":[["垣衣是一种古代的防护服装。","يۈەنيى قەدىمكى زاماندىكى بىر خىل مۇداپىئە كىيىمى.","yüenyi qedimki zamandiki bir xil mudapie kiyimi."]],"埃里温":[["埃里温是亚美尼亚的首都。","ئېرىۋان ئەرمېنىيەنىڭ پايتەختى.","ériwan erméniyening paytexti."]],"执政官":[["执政官是古代官员。","ھاكىمىيەت باشلىقى قەدىمكى دەۋرلەردىكى ئەمەلدار ئىدى.","hakimiyet bashliqi qedimki dewrlerdiki emeldar idi."]],"城域网":[["城域网连接着多个城市节点。","شەھەر تورى كۆپلىگەن شەھەر تۈگۈنلىرىنى تۇتاشتۇرىدۇ.","sheher tori köpligen sheher tügünlirini tutashturidu."]],"基业":[["打牢基业才能长久经营。","ئاساسىي ئىشلارنى مۇستەھكەملىگەندىلا ئۇزۇن مۇددەت باشقۇرغىلى بولىدۇ.","asasiy ishlarni mustehkemligendila uzun muddet bashqurghili bolidu."]],"培勒兹":[["培勒兹教授发表了多篇重要论文。","پروفېسسور پېلېز نۇرغۇن مۇھىم ئىلمىي ماقالىلەرنى ئېلان قىلدى.","proféssor péléz nurghun muhim ilmiy maqalilerni élan qildi."]],"培根":[["培根的哲学思想对后世影响深远。","بېيكوننىڭ پەلسەپىۋى ئىدىيەسى كېيىنكى ئەۋلادلارغا چوڭقۇر تەسىر كۆرسەتتى.","béykonning pelsepiwi idiyesi kéyinki ewladlargha chongqur tesir körsetti."]],"基脚":[["基脚结构需要格外稳固。","ئاساسىي پۇت قۇرۇلمىسى ئالاھىدە مۇقىم بولۇشى كېرەك.","asasiy put qurulmisi alahide muqim bolushi kérek."]],"坚挺":[["股价持续坚挺，表现良好。","پاي چېكىنىڭ باھاسى جىيەنتىڭ داۋاملىشىپ، ياخشى ئىپادىلەندى.","pay chékining bahasi jiyenting dawamliship, yaxshi ipadilendi."]],"报以":[["他报以微笑回应。","ئۇ جاۋابەن كۈلۈمسىرەپ جاۋاب بەردى.","u jawaben külümsirep jawab berdi."]],"塞巴斯蒂安":[["塞巴斯蒂安是一位著名的音乐家。","سېباستىيان داڭلىق بىر مۇزىكانت.","sébastiyan dangliq bir muzikant."]],"墨西哥城":[["墨西哥城是墨西哥的首都。","مېكسىكا شەھىرى مېكسىكىنىڭ پايتەختى.","méksika shehiri méksikining paytexti."]],"壬戌":[["壬戌年举办了盛大的庆典。","رېن-شۈ يىلى داغدۇغىلىق تەنتەنىلىك مۇراسىم ئۆتكۈزۈلدى.","rén-shü yili daghdughiliq tentenilik murasim ötküzüldi."]],"墨巴本":[["墨巴本是一种古老的书写工具。","موسى قەدىمكى زاماندىكى يازۇچ قورالىنىڭ بىر تۈرى ئىدى.","mosi qedimki zamandiki yazuch qoralining bir türi idi."]],"压倒性":[["压倒性的胜利让对手心服口服。","بېسىپ چۈشۈرۈش غەلىبىسى رەقىبنى قەلبىدىن قايىل قىلدى.","bésip chüshürüsh ghelibisi reqibni qelbidin qayil qildi."]],"壮美":[["大自然的壮美令人叹为观止。","تەبىئەتنىڭ ھەيۋەتلىك گۈزەللىكى كىشىنى ھەيران قالدۇرىدۇ.","tebietning heywetlik güzelliki kishini heyran qalduridu."]],"报名表":[["请填写完整的报名表。","تولۇق تىزىملىتىش جەدۋىلىنى تولدۇرۇڭ.","toluq tizimlitish jedwilini toldurung."]],"寿县":[["寿县位于安徽省的北部。","مۇبارەك ناھىيىسى ئەنخۇي ئۆلكىسىنىڭ شىمالىدا جايلاشقان.","mubarek nahiyisi enxuy ölkisining shimalida jaylashqan."]],"外地人":[["外地人在这里需要适应新环境。","باشقا يەردىن كەلگەنلەر بۇ يەردە يېڭى مۇھىتقا ماسلىشىشى كېرەك.","bashqa yerdin kelgenler bu yerde yéngi muhitqa maslishishi kérek."]],"墓道":[["墓道两侧有石俑守护。","قەبرە يولىنىڭ ئىككى تەرىپىدە تاش ھەيكەللەر قوغداپ تۇرىدۇ.","qebre yolining ikki teripide tash heykeller qoghdap turidu."]],"多多少少":[["他多多少少有些担心。","ئۇ ئاز-تولا ئەندىشە قىلىدۇ.","u az-tola endishe qilidu."]],"多巴胺":[["多巴胺能让人产生愉悦感。","دوپامىن كىشىلەردە خۇشاللىق تۇيغۇسى پەيدا قىلالايدۇ.","dopamin kishilerde xushalliq tuyghusi peyda qilalaydu."]],"大吵大闹":[["他们在大吵大闹。","ئۇلار چوڭقۇر ئاۋاز-تۈتەك قىلىشماقتا.","ular chongqur awaz-tütek qilishmaqta."]],"大杓鹬":[["大杓鹬是一种体型较大的水鸟。","چوڭ قىلىچتۇمشۇق چوڭراق گەۋدىلىك سۇ قۇشى.","chong qilichtumshuq chongraq gewdilik su qushi."]],"大提琴手":[["这位大提琴手技艺高超。","بۇ چوڭ ئىسكىرىپكاچىنىڭ ماھارىتى ئىنتايىن يۇقىرى.","bu chong iskiripkachining mahariti intayin yuqiri."]],"大有作为":[["年轻人只要努力，定能大有作为。","ياشلار تىرىشسىلا، چوقۇم چوڭ ئىشلارنى قىلىشقا قادىر بولىدۇ.","yashlar tirishsila, choqum chong ishlarni qilishqa qadir bolidu."]],"大本营":[["大本营是军队的重要指挥中心。","چوڭ بازا ئارمىيەنىڭ مۇھىم قوماندانلىق مەركىزى.","chong baza armiyening muhim qomandanliq merkizi."]],"天择":[["适者生存是自然天择的结果。","ماسلىشالايدىغانلار ياشايدۇ دېگەن نەرسە تەبىئىي تاللاشنىڭ نەتىجىسىدۇر.","maslishalaydighanlar yashaydu dégen nerse tebiiy tallashning netijisidur."]],"大笨象":[["大笨象在森林里慢慢走着。","چوڭ پىل ئورماندا ئاستا ماڭماقتا.","chong pil ormanda asta mangmaqta."]],"天差地别":[["他们的生活方式天差地别。","ئۇلارنىڭ تۇرمۇش ئۇسۇلى ئاسمان بىلەن زېمىندەك پەرقلىق.","ularning turmush usuli asman bilen zémindek perqliq."]],"天有不测风云，人有旦夕祸福":[["人生无常，天有不测风云，人有旦夕祸福。","ھايات بىقارار، ئاسماندا كۈتۈلمىگەن ئۆزگىرىش بار، ئادەمدە ئەتىگەن-ئاخشام بەخت-سائادەت بار.","hayat biqarar, asmanda kütülmigen özgirish bar, ademde etigen-axsham bext-saadet bar."]],"天鹰座":[["天鹰座是夏季夜空的显著星座。","ئاسمان بۈركۈت يۇلتۈز تۈركۈمى ياز كېچىسى ئاسماندىكى كۆرۈنەرلىك يۇلتۇز تۈركۈمىدۇر.","asman bürküt yultüz türkümi yaz kéchisi asmandiki körünerlik yultuz türkümidur."]],"太上":[["太上指至高无上的存在。","تەي شاڭ ئەڭ ئالىي مەۋجۇتلۇققا ئىشارەت قىلىدۇ.","tey shang eng aliy mewjutluqqa isharet qilidu."]],"太半":[["太半表示超过一半。","تەيبەن يېرىمدىن كۆپرەكنى بىلدۈرىدۇ.","teyben yérimdin köprekni bildüridu."]],"失体面":[["他因失体面而羞愧难当。","ئۇ ئىززەت-ھۆرمىتىنى يوقاتقانلىقى ئۈچۈن بەك خىجىل بولدى.","u izzet-hörmitini yoqatqanliqi üchün bek xijil boldi."]],"夷旷":[["夷旷之地，荒无人烟。","تەكشى، كەڭرى زېمىن، ئادەمزات يوق، تەمتىرەش بار.","tekshi, kengri zémin, ademzat yoq, temtiresh bar."]],"天险":[["这座山是天险，难以跨越。","بۇ تاغ تەبىئىي توساق بولۇپ، ئۆتۈش قىيىن.","bu tagh tebiiy tosaq bolup, ötüsh qiyin."]],"奔头":[["他的工作很有奔头。","ئۇنىڭ خىزمىتىنىڭ كەلگۈسى پارلاق.","uning xizmitining kelgüsi parlaq."]],"夹心饼干":[["夹心饼干是零食。","ئارىلىق تولدۇرۇلغان پېچىنە يېمەكلىك.","ariliq toldurulghan péchine yémeklik."]],"奠基人":[["他是公司的奠基人。","ئۇ شىركەتنىڭ يەكتەك سالغۇچىسى.","u shirketning yektek salghuchisi."]],"套套":[["套套是日常用品。","يۈرۈمچە كۈندىلىك ئىشلىتىلىدىغان بۇيۇم.","yürümche kündilik ishlitilidighan buyum."]],"奸官":[["那个奸官贪污受贿。","ئۇ زالىم ئەمەلدار پارىخورلۇق ۋە رىشۋەتخورلۇق قىلدى.","u zalim emeldar parixorluq we rishwetxorluq qildi."]],"奢求":[["不要奢求太多。","كۆپ تەلەپ قىلماڭ.","köp telep qilmang."]],"好好":[["你要好好照顾自己，别太累了。","ئۆزەڭگە ياخشى قارا، بەك چارچاپ كەتمە.","özengge yaxshi qara, bek charchap ketme."]],"好家伙":[["好家伙，这道菜做得太美味了！","ۋاي، بۇ تائام بەك لەززەتلىك ئېتىلىپتۇ!","way, bu taam bek lezzetlik étiliptu!"]],"好命":[["她真是好命，嫁给了一个有钱人。","ئۇنىڭ تەلىيى ھەقىقەتەن ياخشى، بىر باي ئادەمگە ياتلىق بولدى.","uning teliyi heqiqeten yaxshi, bir bay ademge yatliq boldi."]],"妖冶":[["她举止妖冶迷人。","ئۇنىڭ ھەرىكىتى جادۇگەرلەرچە مەھلىيا قىلارلىق.","uning herikiti jadugerlerche mehliya qilarliq."]],"姨丈":[["姨丈是母亲的哥哥，为人和善。","تاغا ئانىنىڭ ئاكىسى بولۇپ، مۇئامىلىسى ئاقكۆڭۈل.","tagha anining akisi bolup, muamilisi aqköngül."]],"孑孑":[["孑孑形容孤独无依的状态。","يالغۇز-يېتىم يالغۇز ۋە تايانچسىز ھالەتنى تەسۋىرلەيدۇ.","yalghuz-yétim yalghuz we tayanchsiz haletni teswirleydu."]],"字节跳动":[["这家公司以字节跳动闻名。","بۇ شىركەت بىتېدۇڭ نامى بىلەن تونۇلغان.","bu shirket bitédung nami bilen tonulghan."]],"孜孜矻矻":[["古人孜孜矻矻地耕读传家。","قەدىمكىلەر ئەۋلادتىن-ئەۋلادقا ئوقۇش-ئوقىتىش بىلەن شۇغۇللىنىپ كەلگەن.","qedimkiler ewladtin-ewladqa oqush-oqitish bilen shughullinip kelgen."]],"子曰":[["孔子曰：‘吾日三省吾身。’","كۇڭزى ئېيتتى: «مەن ھەر كۈنى ئۆزۈمنى ئۈچ قېتىم تەكشۈرىمەن.»","kungzi éytti: «men her küni özümni üch qétim tekshürimen.»"]],"孝南区":[["孝南区以丰富的历史文化闻名。","شياۋنەن رايونى مول تارىخىي مەدەنىيىتى بىلەن داڭلىق.","shyawnen rayoni mol tarixiy medeniyiti bilen dangliq."]],"孝感市":[["孝感市历史悠久，文化深厚。","شياۋگەن شەھىرىنىڭ تارىخى ئۇزۇن، مەدەنىيىتى چوڭقۇر.","shyawgen shehirining tarixi uzun, medeniyiti chongqur."]],"安吉":[["安吉以优美的自然风光闻名。","ئانجى گۈزەل تەبىئىي مەنزىرىسى بىلەن داڭلىق.","anji güzel tebiiy menzirisi bilen dangliq."]],"安太岁":[["安太岁是一种传统道教神灵。","ئەنتەيسۇي ئەنئەنىۋى داۋىزم ئىلاھى.","enteysuy en'eniwi dawizm ilahi."]],"安安":[["安安是个安静乖巧的小女孩。","ئانئەن تىنچ ۋە ئەدەپلىك كىچىك قىز.","an'en tinch we edeplik kichik qiz."]],"安拉":[["安拉是伊斯兰教的主。","ئاللاھ ئىسلام دىنىنىڭ رەببىدۇر.","allah islam dinining rebbidur."]],"安邦定国":[["治国必先安邦定国。","دۆلەتنى ئىدارە قىلىش ئۈچۈن ئالدى بىلەن دۆلەتنى تىنچلاندۇرۇش ۋە مۇقىملاشتۇرۇش كېرەك.","döletni idare qilish üchün aldi bilen döletni tinchlandurush we muqimlashturush kérek."]],"官房长官":[["新任官房长官宣布了新政策。","يېڭى تەيىنلەنگەن باش كاتىپ يېڭى سىياسەتنى ئېلان قىلدى.","yéngi teyinlengen bash katip yéngi siyasetni élan qildi."]],"官俸":[["官俸是官员的主要收入来源。","ئەمەلدارلىق مائاشى ئەمەلدارلارنىڭ ئاساسلىق كىرىم مەنبەسى.","emeldarliq maashi emeldarlarning asasliq kirim menbesi."]],"安瓿瓶":[["安瓿瓶常用于疫苗包装。","ئامپۇلا قۇتا كۆپىنچە ۋاكسىنا قاچىلاشقا ئىشلىتىلىدۇ.","ampula quta köpinche waksina qachilashqa ishlitilidu."]],"安义":[["安义以悠久的历史文化著称。","ئەنيى ئۇزۇن تارىخىي مەدەنىيىتى بىلەن داڭلىق.","enyi uzun tarixiy medeniyiti bilen dangliq."]],"官邸":[["官邸是官员的官居住所。","ئەمەلدارلار تۇرالغۇسى ئەمەلدارلارنىڭ تۇرالغۇ جايىدۇر.","emeldarlar turalghusi emeldarlarning turalghu jayidur."]],"客西马尼园":[["耶稣曾在客西马尼园为即将面临的苦难祷告。","ئىسا جەسىمانىيە باغچىسىدا ئالدىدا تۇرغان ئازاب-ئوقۇبەت ئۈچۈن دۇئا قىلغان.","isa jesimaniye baghchisida aldida turghan azab-oqubet üchün dua qilghan."]],"宜宾市":[["宜宾市是四川南部的城市。","يىبىن شەھىرى سىچۈەننىڭ جەنۇبىدىكى بىر شەھەر.","yibin shehiri sichüenning jenubidiki bir sheher."]],"客堂":[["客堂是传统住宅的会客区。","مېھمانخانا ئەنئەنىۋى ئۆيلەرنىڭ مېھمان قوبۇل قىلىش جايى.","méhmanxana en'eniwi öylerning méhman qobul qilish jayi."]],"家祖":[["家祖是家族中最早的祖先，被世代敬仰。","ئائىلە ئەجدادى ئائىلىدىكى ئەڭ قەدىمكى ئەجداد بولۇپ، ئەۋلادلار تەرىپىدىن ھۆرمەتكە سازاۋەر.","aile ejdadi ailidiki eng qedimki ejdad bolup, ewladlar teripidin hörmetke sazawer."]],"寥寥":[["房间里寥寥几人。","ئۆيدە پەقەت بىر قانچە كىشى بار ئىدى.","öyde peqet bir qanche kishi bar idi."]],"寥寥无几":[["街上行人寥寥无几。","كوچىدىكى مېڭىۋاتقانلار ئىنتايىن ئاز ئىدى.","kochidiki méngiwatqanlar intayin az idi."]],"密西根":[["密西根是汽车制造业中心。","مىشىگان ئاپتوموبىل ئىشلەپچىقىرىش مەركىزىدۇر.","mishigan aptomobil ishlepchiqirish merkizidur."]],"宿县":[["宿县是历史悠久的古县。","سۇشيەن ناھىيىسى ئۇزۇن تارىخقا ئىگە قەدىمىي ناھىيە.","sushyen nahiyisi uzun tarixqa ige qedimiy nahiye."]],"宿迁市":[["宿迁市是江苏省北部的重要城市。","سۇچيەن شەھىرى جياڭسۇ ئۆلكىسىنىڭ شىمالىدىكى مۇھىم شەھەر.","suchyen shehiri jyangsu ölkisining shimalidiki muhim sheher."]],"宿愿":[["实现宿愿是他一生的最大追求。","ئارزۇسىنى ئەمەلگە ئاشۇرۇش ئۇنىڭ پۈتۈن ھاياتىدىكى ئەڭ چوڭ ئىنتىلىشى.","arzusini emelge ashurush uning pütün hayatidiki eng chong intilishi."]],"察察":[["他为人过于察察，常惹人不快。","ئۇ باشقىلارغا بەك تەنقىتچى بولۇپ، كۆپىنچە باشقىلارنى رەنجىتىدۇ.","u bashqilargha bek tenqitchi bolup, köpinche bashqilarni renjitidu."]],"宝宝":[["宝宝今天笑了。","بوۋاق بۈگۈن كۈلدى.","bowaq bügün küldi."]],"实际性":[["实际性决定了方案的成功。","ئەمەلىيلىك لايىھەنىڭ مۇۋەپپەقىيىتىنى بەلگىلەيدۇ.","emeliylik layihening muweppeqiyitini belgileydu."]],"封禁":[["平台实施了封禁措施。","سۇپا چەكلەش تەدبىرىنى يولغا قويدى.","supa cheklesh tedbirini yolgha qoydi."]],"寻死":[["他竟有寻死的念头。","ئۇنىڭ ئۆلۈشنى ئويلاش خىيالى بار ئىكەن.","uning ölüshni oylash xiyali bar iken."]],"小小":[["小小年纪就有大志向。","كىچىك يېشىدا چوڭ ئارزۇ بار.","kichik yéshida chong arzu bar."]],"小百科全书":[["这本小百科全书内容全面。","بۇ كىچىك ئېنسىكلوپېدىيەنىڭ مەزمۇنى ئومۇمىي.","bu kichik énsiklopédiyening mezmuni omumiy."]],"尿尿":[["小朋友在尿尿时很专注。","كىچىك بالىلار سۈيدۈك چىقارغاندا ئىنتايىن دىققەت قىلىدۇ.","kichik balilar süydük chiqarghanda intayin diqqet qilidu."]],"小量":[["他的食量很小，每次只吃小量。","ئۇنىڭ يېمەكلىك مىقدارى بەك ئاز، ھەر قېتىمدا پەقەت ئازغىنا يەيدۇ.","uning yémeklik miqdari bek az, her qétimda peqet azghina yeydu."]],"尖顶":[["这座塔楼有着独特的尖顶设计。","بۇ مۇنار ئۆزىگە خاس ئۇچلۇق تۆپە لايىھەسىگە ئىگە.","bu munar özige xas uchluq töpe layihesige ige."]],"山斑鸠":[["山斑鸠栖息在茂密的森林中。","شەنبەنگۇ ئوقۇرلار قويۇق ئورمانلاردا ياشايدۇ.","shenbengu oqurlar qoyuq ormanlarda yashaydu."]],"屠刀":[["屠刀锋利，用于宰杀牲畜。","سويغۇچ پىچاق ئۆتكۈر بولۇپ، مال-چارۋىنى سويۇشقا ئىشلىتىلىدۇ.","soyghuch pichaq ötkür bolup, mal-charwini soyushqa ishlitilidu."]],"居宅":[["这座居宅历史悠久。","بۇ تۇرالغۇ ئۆي ئۇزۇن تارىخقا ئىگە.","bu turalghu öy uzun tarixqa ige."]],"居心不良":[["他居心不良，令人警惕。","ئۇنىڭ نىيىتى يامان، كىشىلەرنى ھوشيار بولۇشقا ئۈندەيدۇ.","uning niyiti yaman, kishilerni hoshyar bolushqa ündeydu."]],"峨眉乡":[["峨眉乡风景如画。","ئېمېي يېزىسىنىڭ مەنزىرىسى رەسىمدەك گۈزەل.","éméy yézisining menzirisi resimdek güzel."]],"崇洋媚外":[["盲目崇洋媚外不可取。","كۆر-كۆرگە چەتئەلگە يالتىنىش توغرا ئەمەس.","kör-körge chet'elge yaltinish toghra emes."]],"川贝":[["川贝是川贝母的简称，药用价值高。","چۈەنبېي چۈەنبېيمۇنىڭ قىسقارتىلما ئاتىلىشى بولۇپ، دورىلىق قىممىتى يۇقىرى.","chüenbéy chüenbéymuning qisqartilma atilishi bolup, doriliq qimmiti yuqiri."]],"巡测仪":[["巡测仪能精准测量环境数据。","شۈنچېيى ئەسۋابى مۇھىت سانلىق مەلۇماتلىرىنى ئېنىق ئۆلچەيەلەيدۇ.","shünchéyi eswabi muhit sanliq melumatlirini éniq ölcheyeleydu."]],"巍巍":[["巍巍群山连绵起伏，气势磅礴。","ھەيۋەتلىك تاغلار ئۇدۇل-ئۇدۇل سوزۇلۇپ، ھەيۋەتلىك مەنزىرە ھاسىل قىلىدۇ.","heywetlik taghlar udul-udul sozulup, heywetlik menzire hasil qilidu."]],"川建国":[["川建国是网络上的一个热门昵称。","چۈەنجيەنگو تور دۇنياسىدىكى قىزىق لەقەم.","chüenjyengo tor dunyasidiki qiziq leqem."]],"崛地而起":[["高楼崛地而起，改变了城市面貌。","ئېگىز بىنالار يەردىن كۆتۈرۈلۈپ، شەھەر قىياپىتىنى ئۆزگەرتتى.","égiz binalar yerdin kötürülüp, sheher qiyapitini özgertti."]],"山鹡鸰":[["山鹡鸰喜欢在溪流边捕食昆虫。","تاغ چىمچىقى ئېقىن بويىدا ھاشاراتلارنى تۇتۇشنى ياخشى كۆرىدۇ.","tagh chimchiqi éqin boyida hasharatlarni tutushni yaxshi köridu."]],"工作列":[["工作列显示当前任务进度。","خىزمەت تىزىملىكى نۆۋەتتىكى ۋەزىپە ئىلگىرىلەشىنى كۆرسىتىدۇ.","xizmet tizimliki nöwettiki wezipe ilgirileshini körsitidu."]],"岱山":[["岱山是山东的一座名山。","دەيشەن شەندۇڭدىكى بىر داڭلىق تاغ.","deyshen shendungdiki bir dangliq tagh."]],"岳阳":[["岳阳是湖南省的重要城市。","يۈەنيەڭ خۇنەن ئۆلكىسىنىڭ مۇھىم شەھىرى.","yüenyeng xunen ölkisining muhim shehiri."]],"巴巴结结":[["他说话总是巴巴结结，不够流利。","ئۇ سۆزلىگەندە ھەمىشە بارباراڭ-بارباراڭ قىلىپ، راۋان سۆزلىيەلمەيدۇ.","u sözligende hemishe barbarang-barbarang qilip, rawan sözliyelmeydu."]],"工程学":[["工程学是应用数学解决实际问题的一门学科。","ئىنژېنېرلىق پەنى ئەمەلىي مەسىلىلەرنى ھەل قىلىش ئۈچۈن ماتېماتىكىنى قوللىنىدىغان بىر پەندۇر.","inzhénérliq peni emeliy mesililerni hel qilish üchün matématikini qollinidighan bir pendur."]],"市面":[["市面的物价最近有所上涨。","بازار باھاسى يېقىندا ئازراق ئۆسۈش كۆرسەتتى.","bazar bahasi yéqinda azraq ösüsh körsetti."]],"常问问题":[["他常问问题，表现出强烈的好奇心。","ئۇ دائىم سوئال سورايدۇ، كۈچلۈك قىزىقىشىنى نامايان قىلىدۇ.","u daim soal soraydu, küchlük qiziqishini namayan qilidu."]],"平平常常":[["今天的生活平平常常，没有特别的事。","بۈگۈنكى تۇرمۇش ئادەتتىكىچە، ئالاھىدە ئىش يوق.","bügünki turmush adettikiche, alahide ish yoq."]],"庭园":[["这座古老的庭园充满历史气息。","بۇ قەدىمىي ھويلا تارىخىي ھېسسىياتقا تولغان.","bu qedimiy hoyla tarixiy héssiyatqa tolghan."]],"庭训":[["庭训是家族代代相传的教诲。","ئائىلە تەربىيىسى ئەۋلادتىن-ئەۋلادقا مىراس قالىدىغان تەلىم-تەربىيەدۇر.","aile terbiyisi ewladtin-ewladqa miras qalidighan telim-terbiyedur."]],"平阳":[["平阳位于山西省西南部。","پىڭياڭ شەنشى ئۆلكىسىنىڭ جەنۇبىي غەربىدە جايلاشقان.","pingyang shenshi ölkisining jenubiy gherbide jaylashqan."]],"康德":[["康德是德国著名哲学家。","كانت گېرمانىيەنىڭ مەشھۇر پەلسەپىشۇناسى.","kant gérmaniyening meshhur pelsepishunasi."]],"广西":[["广西是中国的一个自治区。","گۇاڭشى جۇڭگونىڭ بىر ئاپتونوم رايونىدۇر.","guangshi junggoning bir aptonom rayonidur."]],"广告衫":[["他穿着一件印着公司标志的广告衫。","ئۇ شىركەت بەلگىسى بېسىلغان ئېلان كۆڭلىكى كىيىۋالغان.","u shirket belgisi bésilghan élan köngliki kiyiwalghan."]],"弗兰兹":[["弗兰兹是一位著名的音乐家。","فرانتس بىر داڭلىق مۇزىكانت.","frants bir dangliq muzikant."]],"建党":[["建党纪念日意义重大。","پارتىيە قۇرۇلغانلىق خاتىرە كۈنىنىڭ ئەھمىيىتى زور.","partiye qurulghanliq xatire künining ehmiyiti zor."]],"弄伤":[["他不小心弄伤了手指。","ئۇ سەل قاراپ بارمىقىنى يارىلاندۇرۇۋالدى.","u sel qarap barmiqini yarilanduruwaldi."]],"张怡宁":[["张怡宁是中国的顶尖乒乓球选手。","جاڭ يىنىڭ جۇڭگونىڭ ئالدىنقى قاتارلىق تەننېس توپچىسى.","jang yining junggoning aldinqi qatarliq tennés topchisi."]],"张开":[["他张开双臂迎接朋友。","ئۇ قوللىرىنى ئېچىپ دوستلىرىنى قارشى ئالدى.","u qollirini échip dostlirini qarshi aldi."]],"弱碱":[["弱碱与酸反应时不会剧烈放热。","ئاجىز ئىشلار تۇز بىلەن رېئاكسىيىلەشكەندە كۈچلۈك ئىسسىقلىق چىقارمايدۇ.","ajiz ishlar tuz bilen réaksiyileshkende küchlük issiqliq chiqarmaydu."]],"张僧繇":[["张僧繇以画龙闻名。","جاڭ سېڭيۇ ئەجدىھا رەسىمى بىلەن داڭق چىقارغان.","jang séngyu ejdiha resimi bilen dangq chiqarghan."]],"彩扩":[["彩扩后的照片色彩更加鲜艳。","Rəڭلىك كېڭەيتىلگەن سۈرەتلەرنىڭ رەڭگى تېخىمۇ يورۇق.","Rənglik kéngeytilgen süretlerning renggi téximu yoruq."]],"强相互作用":[["强相互作用是基本力之一。","كۈچلۈك ئۆزئارا تەسىر ئاساسىي كۈچلەرنىڭ بىرىدۇر.","küchlük öz'ara tesir asasiy küchlerning biridur."]],"徒劳无功":[["这场争论完全是徒劳无功。","بۇ تالاش-تارتىش پۈتۈنلەي بىكار.","bu talash-tartish pütünley bikar."]],"得志":[["他终于得志，实现了多年的梦想。","ئۇ ئاخىرى مەقسىتىگە يەتتى، كۆپ يىللىق چۈشىنى ئەمەلگە ئاشۇردى.","u axiri meqsitige yetti, köp yilliq chüshini emelge ashurdi."]],"后置":[["动词的宾语有时可以后置。","پېئىلنىڭ تولۇقلىغۇچىسى بەزىدە ئارقىغا يۆتكىلىشى مۇمكىن.","péilning toluqlighuchisi bezide arqigha yötkilishi mumkin."]],"后轮":[["后轮驱动让车辆更稳定。","ئارقا چاق تارتىشى ماشىنىنى تېخىمۇ مۇقىم قىلىدۇ.","arqa chaq tartishi mashinini téximu muqim qilidu."]],"从从容容":[["她面对困难总能从从容容。","ئۇ قىيىنچىلىققا دۇچ كەلگەندە ھەمىشە ئارام ۋە بىخەتەر بولالايدۇ.","u qiyinchiliqqa duch kelgende hemishe aram we bixeter bolalaydu."]],"德化县":[["德化县位于福建省泉州市。","دېخۇا ناھىيىسى فۇجيەن ئۆلكىسى چۈەنجۇ شەھىرىدە جايلاشقان.","déxua nahiyisi fujyen ölkisi chüenju shehiride jaylashqan."]],"心房颤动":[["他患有轻微的心房颤动。","ئۇ يېنىك دەرىجىدىكى يۈرەكچە تىترەش كېسىلىگە گىرىپتار بولغان.","u yénik derijidiki yürekche titresh késilige giriptar bolghan."]],"忙忙叨叨":[["她忙忙叨叨地安排着一切。","ئۇ ئالدىراپ-تېنەپ ھەممە ئىشنى ئورۇنلاشتۇرۇۋاتىدۇ.","u aldirap-ténep hemme ishni orunlashturuwatidu."]],"念诵":[["每天早晨，他都会念诵经文。","ھەر كۈنى ئەتىگەندە ئۇ ئوقۇپ تەسبىھ ئېيتىدۇ.","her küni etigende u oqup tesbih éytidu."]],"忸忸怩怩":[["她说话总是忸忸怩怩，让人捉摸不透。","ئۇ سۆزلىگەندە ھەمىشە تارتىنىپ سۆزلەيدۇ، كىشىنى چۈشىنەلمەيدىغان قىلىپ قويىدۇ.","u sözligende hemishe tartinip sözleydu, kishini chüshinelmeydighan qilip qoyidu."]],"德雷福斯":[["德雷福斯是法国历史上的冤案人物。","درېيفۇس فرانسىيە تارىخىدىكى خاتا ئىش پېرسونى.","dréyfus fransiye tarixidiki xata ish pérsoni."]],"恬和":[["他的性格恬和友善。","ئۇنىڭ خاراكتېرى ئىناق ۋە دوستانە.","uning xaraktéri inaq we dostane."]],"悉悉索索":[["树叶发出悉悉索索声。","دەرەخ يوپۇرماقلىرىدىن شىتىر-شىتىر ئاۋاز چىقاتتى.","derex yopurmaqliridin shitir-shitir awaz chiqatti."]],"悠着":[["悠着点，别太着急。","ئالدىراپ كەتمە، بەك ئاپىرىما.","aldirap ketme, bek apirima."]],"闷雷":[["远处传来闷雷，让人不安。","يىراقتىن پىسە گۈلدۈرەش ئاڭلىنىپ، كىشىنى بىئارام قىلىدۇ.","yiraqtin pise güldüresh anglinip, kishini biaram qilidu."]],"悻悻":[["他悻悻地离开了现场。","ئۇ خاپا بولۇپ ئورنىدىن كەتتى.","u xapa bolup ornidin ketti."]],"恶唑啉酮":[["恶唑啉酮具有显著的抗菌作用。","ئوكسازولىنون ئېنىق باكتېرىيەگە قارشى تۇرۇش رولى بار.","oksazolinon éniq baktériyege qarshi turush roli bar."]],"愚人":[["愚人节玩笑让人哭笑不得。","ئەخمىقلار كۈنىدىكى چاقچاق كىشىنى كۈلدۈرۈپ يىغلىتىدۇ.","exmiqlar künidiki chaqchaq kishini küldürüp yighlitidu."]],"恶言伤人":[["恶言伤人，容易破坏人际关系。","ناچار سۆزلەر كىشىگە ئازار بېرىپ، كىشىلىك مۇناسىۋەتنى ئاسان بۇزىدۇ.","nachar sözler kishige azar bérip, kishilik munasiwetni asan buzidu."]],"爱哭鬼":[["别叫爱哭鬼，快擦干眼泪！","يىغلىماقچى دېمەڭ، تېز كۆز يېشىڭىزنى سۈرتۈڭ!","yighlimaqchi démeng, téz köz yéshingizni sürtüng!"]],"惨案":[["这起惨案引起了社会关注。","بۇ پاجىئەلىك ۋەقە جەمئىيەتنىڭ دىققىتىنى تارتقان.","bu pajielik weqe jem'iyetning diqqitini tartqan."]],"惨烈":[["战斗异常惨烈。","جەڭ ئىنتايىن شىددەتلىك ئىدى.","jeng intayin shiddetlik idi."]],"爱爱":[["爱爱是孩子们最喜欢的游戏之一。","مېھىر-مۇھەببەت بالىلارنىڭ ئەڭ ياخشى كۆرىدىغان ئويۇنلىرىنىڭ بىرىدۇر.","méhir-muhebbet balilarning eng yaxshi köridighan oyunlirining biridur."]],"慷慨捐生":[["他慷慨捐生，帮助了许多人。","ئۇ سەخىيلىك بىلەن ھاياتىنى بېغىشلاپ، نۇرغۇن كىشىلەرگە ياردەم قىلدى.","u sexiylik bilen hayatini béghishlap, nurghun kishilerge yardem qildi."]],"憧憧":[["远处灯火憧憧，夜色迷人。","يىراقتا چىراغلار پارقىراپ، كېچە مەنزىرىسى مەپتۇن قىلارلىق ئىدى.","yiraqta chiraghlar parqirap, kéche menzirisi meptun qilarliq idi."]],"惯犯":[["这个惯犯多次被警方抓获。","بۇ ئادەتلەنگەن جىنايەتچى ساقچىلار تەرىپىدىن بىر قانچە قېتىم تۇتۇلدى.","bu adetlengen jinayetchi saqchilar teripidin bir qanche qétim tutuldi."]],"悭俭":[["他悭俭节约，从不浪费。","ئۇ چىقىمچىل ۋە تېجەشچان، ھەرگىز ئىسراپ قىلمايدۇ.","u chiqimchil we téjeshchan, hergiz israp qilmaydu."]],"想不通":[["这件事我实在想不通。","بۇ ئىشنى مەن ھەقىقەتەن چۈشەنەلمىدىم.","bu ishni men heqiqeten chüshenelmidim."]],"㤽㤽":[["他㤽㤽地坐在角落里。","ئۇ خۇنۈك ھالدا بۇلۇڭدا ئولتۇردى.","u xunük halda bulungda olturdi."]],"恹恹":[["他恹恹地躺在床上不愿起身。","ئۇ ھالسىز ھالدا كارىۋاتتا يېتىپ تۇرۇشقا ئۇنىمىدى.","u halsiz halda kariwatta yétip turushqa unimidi."]],"懵懵懂懂":[["他懵懵懂懂地答应了。","ئۇ ھېچنىمىنى چۈشەنمەي ۋەدە بەردى.","u héchnimini chüshenmey wede berdi."]],"恋恋":[["他恋恋不舍地离开了家乡。","ئۇ يۇرتىدىن ئايرىلغاندا ئىنتايىن سېغىنىش بىلەن ئايرىلدى.","u yurtidin ayrilghanda intayin séghinish bilen ayrildi."]],"戊唑醇":[["戊唑醇是一种抗真菌药物。","پېنتاكونازول بىر زەمبۇرۇغقا قارشى دورا.","péntakonazol bir zemburughqa qarshi dora."]],"戋戋":[["他收入微薄，生活十分戋戋。","ئۇنىڭ كىرىمى ئاز، تۇرمۇشى ئىنتايىن جاپالىق.","uning kirimi az, turmushi intayin japaliq."]],"戴尔":[["这台戴尔电脑很耐用。","بۇ دېلل كومپيۇتېرى ناھايىتى چىداملىق.","bu déll kompyutéri nahayiti chidamliq."]],"戴维斯杯":[["戴维斯杯是男子网球赛事。","دېۋىس كۇبوكى ئەرلەر تېننىس مۇسابىقىسىدۇر.","déwis kuboki erler ténnis musabiqisidur."]],"戈壁沙漠":[["戈壁沙漠是中国最大的沙漠。","گوبى قۇملۇقى جۇڭگودىكى ئەڭ چوڭ قۇملۇقتۇر.","gobi qumluqi junggodiki eng chong qumluqtur."]],"户口本":[["户口本必须随身携带。","نوپۇس دەپتەرىنى چوقۇم ئۆز يېنىدا ئېلىپ يۈرۈش كېرەك.","nopus depterini choqum öz yénida élip yürüsh kérek."]],"手残":[["她的手残，做手工总失败。","ئۇنىڭ قولى مايىپ، قول ھۈنەرۋەنچىلىك قىلغاندا ھەمىشە مەغلۇپ بولىدۇ.","uning qoli mayip, qol hünerwenchilik qilghanda hemishe meghlup bolidu."]],"才不":[["他才不承认自己错了，总是固执己见。","ئۇ ئۆزىنىڭ خاتا قىلغانلىقىنى ھەرگىز ئېتىراپ قىلمايدۇ، ھەمىشە ئۆز پىكرىدە چىڭ تۇرىدۇ.","u özining xata qilghanliqini hergiz étirap qilmaydu, hemishe öz pikride ching turidu."]],"托克劳":[["托克劳是太平洋岛国。","توكېلاۋ تىنچ ئوكيان ئارىلىدىكى دۆلەت.","tokélaw tinch okyan arilidiki dölet."]],"打孔卡":[["这种打孔卡用于存储数据。","بۇ خىل تۆشۈكلۈك كارتىدىن سانلىق مەلۇمات ساقلاشقا ئىشلىتىلىدۇ.","bu xil töshüklük kartidin sanliq melumat saqlashqa ishlitilidu."]],"打鼓":[["他喜欢打鼓。","ئۇ دۇمباق چېلىشنى ياخشى كۆرىدۇ.","u dumbaq chélishni yaxshi köridu."]],"扳平":[["他们扳平了比分，赢得比赛。","ئۇلار نومۇرنى تەڭلەشتۈرۈپ، مۇسابىقىدە غەلىبە قىلدى.","ular nomurni tengleshtürüp, musabiqide ghelibe qildi."]],"扳钳":[["他用扳钳剪断电线。","ئۇ كاڭلىق ئەسۋاب بىلەن توك سىمىنى كەستى.","u kangliq eswab bilen tok simini kesti."]],"批点":[["批点过程中要注意语气委婉。","تەنقىدىي ئىزاھات جەريانىدا ئاۋاز ئەھۋالىغا دىققەت قىلىش كېرەك.","tenqidiy izahat jeryanida awaz ehwaligha diqqet qilish kérek."]],"抗组织胺":[["药物能对抗组织胺反应。","دورا گىستامىن رېئاكسىيەسىگە قارشى تۇرالايدۇ.","dora gistamin réaksiyesige qarshi turalaydu."]],"找回":[["她找回了丢失的项链。","ئۇ يوقىتىپ قويغان مارجاننى تېپىۋالدى.","u yoqitip qoyghan marjanni tépiwaldi."]],"拆账":[["我们需要拆账处理不同费用。","بىز ئوخشاش بولمىغان چىقىملارنى بۆلۈپ ھېسابلاشنى ئېھتىياج قىلىمىز.","biz oxshash bolmighan chiqimlarni bölüp hésablashni éhtiyaj qilimiz."]],"拇指":[["他用拇指按住了开关。","ئۇ باش بارمىقى بىلەن ئوچۇرغۇچنى بېسىپ تۇردى.","u bash barmiqi bilen ochurghuchni bésip turdi."]],"批改":[["老师认真批改学生的作业。","ئوقۇتقۇچى ئوقۇغۇچىلارنىڭ تاپشۇرۇقىنى ئەستايىدىل تۈزەتتى.","oqutquchi oqughuchilarning tapshuruqini estayidil tüzetti."]],"拉尔夫":[["拉尔夫是球队的核心球员。","رالف كوماندىنىڭ ئاساسلىق توپچىسى.","ralf komandining asasliq topchisi."]],"招供":[["他终于招供了。","ئۇ ئاخىرى ئىقرار قىلدى.","u axiri iqrar qildi."]],"拳拳":[["拳拳到肉，每一击都充满力量。","ھەر بىر مۇشت گۆشكە تەگدى، ھەر بىر زەربە كۈچكە تولدى.","her bir musht göshke tegdi, her bir zerbe küchke toldi."]],"拳脚相向":[["两人最终拳脚相向，大打出手。","ئىككىيلەن ئاخىرىدا مۇشتلىشىپ، قاتتىق ئۇرۇشتى.","ikkiylen axirida mushtliship, qattiq urushti."]],"指数基金":[["指数基金是一种被动投资工具。","كۆرسەتكۈچ فوندى پاسسىپ مەبلەغ سېلىش قورالى.","körsetküch fondi passip meblegh sélish qorali."]],"排难解纷":[["他擅长排难解纷。","ئۇ قىيىنچىلىقلارنى ھەل قىلىش ۋە تالاش-تارتىشلارنى يوقىتىشقا ماھىر.","u qiyinchiliqlarni hel qilish we talash-tartishlarni yoqitishqa mahir."]],"探求":[["他一生都在探求真理的奥秘。","ئۇ پۈتۈن ھاياتىدا ھەقىقەتنىڭ سىرىنى ئىزدەيدۇ.","u pütün hayatida heqiqetning sirini izdeydu."]],"提到":[["他在信中提到了家乡的变化。","ئۇ خېتىدە يۇرتىنىڭ ئۆزگىرىشلىرىنى تىلغا ئالدى.","u xétide yurtining özgirishlirini tilgha aldi."]],"提现":[["提现操作需要验证身份信息。","نەق پۇل ئېلىش مەشغۇلاتى شەخسىيەت ئۇچۇرىنى دەلىللەشنى تەلەپ قىلىدۇ.","neq pul élish meshghulati shexsiyet uchurini delilleshni telep qilidu."]],"扬子鳄":[["扬子鳄是中国特有的珍稀动物。","يانگتسى تىمىساھى جۇڭگوغا خاس ناياب ھايۋان.","yangtsi timisahi junggogha xas nayab haywan."]],"提述":[["这段文字对事件进行了提述。","بۇ پارچە تېكىست ۋەقەگە ئىشارەت قىلدى.","bu parche tékist weqege isharet qildi."]],"插卡式":[["这款设备是插卡式的，方便使用。","بۇ ئۈسكۈنە كارتا قىستۇرما تىپلىق، ئىشلىتىشكە قۇلايلىق.","bu üsküne karta qisturma tipliq, ishlitishke qulayliq."]],"推推搡搡":[["人群推推搡搡地向前涌。","كىشىلەر توپى ئىتتىرىشىپ ئالدىغا ئېقىپ كەتتى.","kishiler topi ittiriship aldigha éqip ketti."]],"摩西律法":[["摩西律法规定了诸多戒律。","مۇسا قانۇنى نۇرغۇن پەرزلەرنى بەلگىلىگەن.","musa qanuni nurghun perzlerni belgiligen."]],"撒都该人":[["撒都该人拒绝相信来世的存在。","سادۇقىيلار ئاخىرەتنىڭ مەۋجۇتلۇقىغا ئىشەنمەيدۇ.","saduqiylar axiretning mewjutluqigha ishenmeydu."]],"折纸":[["他擅长用折纸制作各种模型。","ئۇ قەغەز قاتلاش ئارقىلىق تۈرلۈك مودېللارنى ياساشقا ماھىر.","u qeghez qatlash arqiliq türlük modéllarni yasashqa mahir."]],"挥斥":[["他挥斥方遒，充满激情。","ئۇ ئىنتايىن ھېسسىياتلىق ھالدا ئىرادىسىنى ئىپادىلىدى.","u intayin héssiyatliq halda iradisini ipadilidi."]],"抚顺":[["抚顺是辽宁省的一座工业城市。","فۇشۈن لياۋنىڭ ئۆلكىسىدىكى بىر سانائەت شەھىرى.","fushün lyawning ölkisidiki bir sanaet shehiri."]],"摩天":[["摩天大楼高耸入云。","ئاسمان-بىنا بۇلۇتلارغا تەڭلەشكەن.","asman-bina bulutlargha tengleshken."]],"摩根·弗里曼":[["摩根·弗里曼是一位著名演员。","مورگان فرىمەن تونۇلغان بىر ئارتىس.","morgan frimen tonulghan bir artis."]],"支支吾吾":[["他支支吾吾，说不出完整的话。","ئۇ پىچىرلاپ-پىچىرلاپ تولۇق گەپ قىلالمايدۇ.","u pichirlap-pichirlap toluq gep qilalmaydu."]],"政治委员":[["政治委员负责思想指导工作。","سىياسىي كومىسسار ئىدىيە يېتەكچىلىك خىزمىتىگە مەسئۇل.","siyasiy komissar idiye yétekchilik xizmitige mes'ul."]],"教职员工":[["学校里的教职员工非常敬业。","مەكتەپتىكى ئوقۇتقۇچى-خادىملار ئىنتايىن ئىخلاسمەن.","mekteptiki oqutquchi-xadimlar intayin ixlasmen."]],"故家子弟":[["他出身于书香门第，是典型的故家子弟。","ئۇ كىتابخان ئائىلىسىدىن چىققان بولۇپ، تىپىك كونا ئائىلە پەرزەنتى ئىدى.","u kitabxan ailisidin chiqqan bolup, tipik kona aile perzenti idi."]],"叙永县":[["叙永县风景优美。","شۈيۇڭ ناھىيەسىنىڭ مەنزىرىسى گۈزەل.","shüyung nahiyesining menzirisi güzel."]],"数理分析":[["数理分析用于预测市场趋势的变化。","ماتېماتىكىلىق ئانالىز بازار يۈزلىنىشىنىڭ ئۆزگىرىشىنى مۆلچەرلەشكە ئىشلىتىلىدۇ.","matématikiliq analiz bazar yüzlinishining özgirishini mölcherleshke ishlitilidu."]],"斑姬啄木鸟":[["斑姬啄木鸟正在树干上觅食。","داغلىق تەلەي قۇشى دەرەخ تۈۋىدە ئوزۇق ئىزدەۋاتىدۇ.","daghliq teley qushi derex tüwide ozuq izdewatidu."]],"斑斑":[["他的脸上布满了大大小小的斑斑。","ئۇنىڭ يۈزى چوڭ-كىچىك داغلار بىلەن قاپلانغان.","uning yüzi chong-kichik daghlar bilen qaplanghan."]],"斗南":[["斗南以盛产水果而著称。","دونان مول مېۋە ئىشلەپچىقىرىشى بىلەن داڭلىقتۇر.","donan mol méwe ishlepchiqirishi bilen dangliqtur."]],"斜眼":[["他斜眼看着对方，显得不友好。","ئۇ قارشى تەرەپكە يانتايىپ قاراپ، دوستانە ئەمەس كۆرۈندى.","u qarshi terepke yantayip qarap, dostane emes köründi."]],"新源":[["新源是云南省的一个县。","شىنيۈەن يۈننەن ئۆلكىسىدىكى بىر ناھىيە.","shinyüen yünnen ölkisidiki bir nahiye."]],"斯科普里":[["斯科普里是马其顿的首都。","سكوپيې ماكېدونىيەنىڭ پايتەختى.","skopyé makédoniyening paytexti."]],"斯莱特林":[["斯莱特林是哈利波特的学院。","سلىتېرىن خاررى پوتتېرنىڭ شۆبىسى.","slitérin xarri pottérning shöbisi."]],"新乐":[["新乐市历史悠久，文化深厚。","شىنلې شەھىرىنىڭ تارىخى ئۇزۇن، مەدەنىيىتى چوڭقۇر.","shinlé shehirining tarixi uzun, medeniyiti chongqur."]],"断灭":[["他的希望彻底断灭了。","ئۇنىڭ ئۈمىدى پۈتۈنلەي ئۈزۈلدى.","uning ümidi pütünley üzüldi."]],"断续":[["他的声音断续难辨。","ئۇنىڭ ئاۋازى ئۈزۈلۈپ-ئۈزۈلۈپ ئاڭلىنىشى قىيىن.","uning awazi üzülüp-üzülüp anglinishi qiyin."]],"新闻发言人":[["新闻发言人回答了提问。","خەۋەر سۆزلىگۈچىسى سوراقلارغا جاۋاب بەردى.","xewer sözligüchisi soraqlargha jawab berdi."]],"方向盘":[["他转动方向盘，让汽车转弯。","ئۇ رولنى ئايلاندۇرۇپ، ماشىنىنى بۇرالدى.","u rolni aylandurup, mashinini buraldi."]],"方块舞":[["方块舞是一种传统的舞蹈表演。","كۇب شەكىللىك ئۇسسۇل ئەنئەنىۋى ئۇسسۇل ئويۇنى.","kub shekillik ussul en'eniwi ussul oyuni."]],"施工单位":[["施工单位负责道路扩建。","قۇرۇلۇش بىرلىكى يول كېڭەيتىشكە مەسئۇل.","qurulush birliki yol kéngeytishke mes'ul."]],"旁遮普省":[["旁遮普省以农业闻名。","پەنجاب ئۆلكىسى دېھقانچىلىق بىلەن داڭلىق.","penjab ölkisi déhqanchiliq bilen dangliq."]],"旅充":[["旅充服务十分便捷。","ساياھەتچىلىك زەرەپ قىلىش مۇلازىمىتى ئىنتايىن قولايلىق.","sayahetchilik zerep qilish mulazimiti intayin qolayliq."]],"旅居":[["他在国外旅居多年。","ئۇ چەت ئەلدە كۆپ يىل تۇرۇپ قالدى.","u chet elde köp yil turup qaldi."]],"旋转极":[["旋转极决定了旋转的方向。","ئايلانما قۇتۇپ ئايلىنىش يۆنىلىشىنى بەلگىلەيدۇ.","aylanma qutup aylinish yönilishini belgileydu."]],"日来":[["他今日来拜访了我们。","ئۇ بۈگۈن بىزگە يوقلاپ كەلدى.","u bügün bizge yoqlap keldi."]],"昂仁县":[["昂仁县位于山区。","ئاڭرىن ناھىيىسى تاغلىق رايوندا جايلاشقان.","angrin nahiyisi taghliq rayonda jaylashqan."]],"旬输月送":[["旬输月送是古代税收制度。","شۈنشۇيەسۇڭ قەدىمكى زامان باج ئېلىش تۈزۈمى.","shünshuyesung qedimki zaman baj élish tüzümi."]],"明知故问":[["他明知故问，让人很不耐烦。","ئۇ بىلىپ تۇرۇپ سورىدى، بۇ كىشىنى بەك زېرىكتۈردى.","u bilip turup soridi, bu kishini bek zériktürdi."]],"春日":[["春日暖阳让人心情愉悦。","باھار كۈنىنىڭ ئىللىق قۇياشى كىشىنىڭ كۆڭلىنى خۇشال قىلىدۇ.","bahar künining illiq quyashi kishining könglini xushal qilidu."]],"星星之火":[["星星之火可以燎原，力量不可小觑。","يۇلتۇز ئوتى دالانى كۆيدۈرەلەيدۇ، كۈچىنى كەمسىتىشكە بولمايدۇ.","yultuz oti dalani köydüreleydu, küchini kemsitishke bolmaydu."]],"星期一":[["星期一早上，他准时到达办公室开始工作。","دۈشەنبە ئەتىگەندە ئۇ ۋاقتىدا ئىشخانىغا يېتىپ كېلىپ خىزمەتنى باشلىدى.","düshenbe etigende u waqtida ishxanigha yétip kélip xizmetni bashlidi."]],"晚场":[["晚场指晚上举行的演出或活动。","كەچ مەيدانى كەچتە ئۆتكۈزۈلىدىغان نومۇر ياكى پائالىيەتنى كۆرسىتىدۇ.","kech meydani kechte ötküzülidighan nomur yaki paaliyetni körsitidu."]],"普度众生":[["佛教倡导普度众生的理念。","بۇددا دىنى ھەممە جانلىقلارنى قۇتقۇزۇش ئىدىيەسىنى تەشەببۇس قىلىدۇ.","budda dini hemme janliqlarni qutquzush idiyesini teshebbus qilidu."]],"暖瓶":[["这个暖瓶能长时间保持温度。","بۇ تېرموس ئۇزۇن ۋاقىت تېمپېراتۇرىنى ساقلاپ تۇرالايدۇ.","bu térmos uzun waqit témpératurini saqlap turalaydu."]],"有效期":[["会员的有效期为一年。","ئەزالىقنىڭ ئۈنۈملۈك مۇددىتى بىر يىل.","ezaliqning ünümlük mudditi bir yil."]],"朋克":[["他喜欢朋克音乐的风格。","ئۇ پانك مۇزىكىسىنىڭ ئۇسلۇبىنى ياخشى كۆرىدۇ.","u pank muzikisining uslubini yaxshi köridu."]],"服侍":[["他服侍老人多年，很孝顺。","ئۇ ياشانغانلارغا كۆپ يىللاردىن بېرى خىزمەت قىلىپ كەلدى، ناھايىتى پىدائىي.","u yashanghanlargha köp yillardin béri xizmet qilip keldi, nahayiti pidaiy."]],"服服":[["他服服帖帖地听从安排。","ئۇ ئىتائەتچانلىق بىلەن ئورۇنلاشتۇرۇشقا بويسۇندى.","u itaetchanliq bilen orunlashturushqa boysundi."]],"服服帖帖":[["她总是服服帖帖地配合工作。","ئۇ ھەمىشە ئىتائەتچانلىق بىلەن خىزمەتكە ماسلىشىدۇ.","u hemishe itaetchanliq bilen xizmetke maslishidu."]],"期望值":[["他的期望值远远高于实际结果。","ئۇنىڭ كۈتۈش قىممىتى ئەمەلىي نەتىجىدىن خېلى يۇقىرى.","uning kütüsh qimmiti emeliy netijidin xéli yuqiri."]],"期期艾艾":[["他期期艾艾地解释着自己的理由。","ئۇ سەۋەبلىرىنى ئىككىلىنىپ چۈشەندۈردى.","u seweblirini ikkilinip chüshendürdi."]],"末日论":[["末日论是宗教中关于世界终结的说法。","ئاخىرەتچىلىك دىنلاردا دۇنيانىڭ ئاخىرلىشىشى توغرىسىدىكى قاراش.","axiretchilik dinlarda dunyaning axirlishishi toghrisidiki qarash."]],"未羊":[["未羊是古代祭祀用羊。","قوي يىلى قەدىمكى زاماندا قۇربانلىققا ئىشلىتىلىدىغان قوي ئىدى.","qoy yili qedimki zamanda qurbanliqqa ishlitilidighan qoy idi."]],"本行":[["本行提供多种金融理财产品。","بۇ بانكا ھەر خىل پۇل-مۇئامىلە ئىدارە قىلىش مەھسۇلاتلىرىنى تەمىنلەيدۇ.","bu banka her xil pul-muamile idare qilish mehsulatlirini teminleydu."]],"杜鹃座":[["杜鹃座是南半球的一个星座。","دۇجۈەن يۇلتۇز ئەمەلى جەنۇبىي يېرىم شارنىڭ بىر يۇلتۇز ئەمەلى.","dujüen yultuz emeli jenubiy yérim sharning bir yultuz emeli."]],"杳杳":[["杳杳形容遥远或幽深的样子。","ياۋياۋ يىراق ياكى چوڭقۇر كۆرۈنۈشنى تەسۋىرلەيدۇ.","yawyaw yiraq yaki chongqur körünüshni teswirleydu."]],"松下电器":[["这家店卖各种松下电器。","بۇ دۇكان ھەر خىل پاناسونىك ئېلېكتر سايمانلىرىنى ساتىدۇ.","bu dukan her xil panasonik éléktr saymanlirini satidu."]],"李连杰":[["李连杰是中国著名的动作演员。","لى ليەنجېي جۇڭگونىڭ داڭلىق ھەرىكەت ئارتىسى.","li lyenjéy junggoning dangliq heriket artisi."]],"枝江市":[["枝江市以丰富的水资源闻名。","جىجياڭ شەھىرى مول سۇ بايلىقى بىلەن تونۇلغان.","jijyang shehiri mol su bayliqi bilen tonulghan."]],"某地":[["某地发生了意外事故。","بىرەر يەردە تۇيۇقسىز ھادىسە يۈز بەردى.","birer yerde tuyuqsiz hadise yüz berdi."]],"枸橘":[["枸橘是常见的观赏植物。","گوجۈ بىر خىل كۆپ ئۇچرايدىغان تاماشا ئۆسۈملۈكى.","gojü bir xil köp uchraydighan tamasha ösümlüki."]],"柰子":[["柰子是一种口感酸甜的水果。","نەيزى بىر خىل تاتلىق-چۈچۈك تەملىك مېۋىدۇر.","neyzi bir xil tatliq-chüchük temlik méwidur."]],"柳河":[["柳河是一条河流，流经多个城市，对当地经济有重要影响。","ليۇخې بىر دەريا بولۇپ، بىر قانچە شەھەردىن ئېقىپ ئۆتىدۇ ۋە يەرلىك ئىقتىسادقا مۇھىم تەسىر كۆرسىتىدۇ.","lyuxé bir derya bolup, bir qanche sheherdin éqip ötidu we yerlik iqtisadqa muhim tesir körsitidu."]],"枳壳":[["枳壳具有理气消食的功效。","تۈرۈمچى قوبىغىچىلىق ۋە يېمەكلىكنى ھەزىم قىلىش ئۈنۈمىگە ئىگە.","türümchi qobighichiliq we yémeklikni hezim qilish ünümige ige."]],"栩栩":[["她的表演栩栩如生。","ئۇنىڭ ئىپادىسى جانلىق ئىدى.","uning ipadisi janliq idi."]],"核战":[["核战可能导致全球性的灾难。","يادرو ئۇرۇشى پۈتۈن دۇنيالىق ئاپەتكە سەۋەب بولۇشى مۇمكىن.","yadro urushi pütün dunyaliq apetke seweb bolushi mumkin."]],"林雪平":[["林雪平是一位著名的演员。","لىن شۈەپىڭ داڭلىق ئارتىس.","lin shüeping dangliq artis."]],"果戈里":[["果戈里是著名的俄罗斯作家。","گوگول داڭلىق رۇس يازغۇچىسى.","gogol dangliq rus yazghuchisi."]],"案兵束甲":[["敌人案兵束甲，准备进攻。","دۈشمەن ئەسكەرلىرىنى توختىتىپ قوراللىرىنى تاشلاپ، ھۇجۇمغا تەييارلىق قىلدى.","düshmen eskerlirini toxtitip qorallirini tashlap, hujumgha teyyarliq qildi."]],"桐柏县":[["桐柏县地处河南省南部。","تۇڭبەي ناھىيىسى خېنەن ئۆلكىسىنىڭ جەنۇبىي قىسمىدا جايلاشقان.","tungbey nahiyisi xénen ölkisining jenubiy qismida jaylashqan."]],"格子间":[["格子间是办公室的常见布局。","كاتەك ئۆي ئىشخانىنىڭ ئادەتتىكى ئورۇنلاشتۇرۇلۇشى.","katek öy ishxanining adettiki orunlashturulushi."]],"桑树":[["桑树是养蚕的重要植物。","تۇت يىپەك قۇرتى بېقىشنىڭ مۇھىم ئۆسۈملۈكى.","tut yipek qurti béqishning muhim ösümlüki."]],"桑科":[["桑科植物包括多种果树。","ساڭكە ئۆسۈملۈكلەر تۈرلۈك مېۋىلىك دەرەخلەرنى ئۆز ئىچىگە ئالىدۇ.","sangke ösümlükler türlük méwilik derexlerni öz ichige alidu."]],"棋手":[["这位棋手在比赛中展现了高超的技巧。","بۇ چەمبىرەكچى مۇسابىقىدە يۇقىرى ماھارىتىنى نامايان قىلدى.","bu chembirekchi musabiqide yuqiri maharitini namayan qildi."]],"棋王":[["他被誉为新一代的棋王，无人能敌。","ئۇ يېڭى ئەۋلاد چەمبىرەك پادىشاھى دەپ ئاتىلىدۇ، ھېچكىم ئۇنىڭغا تەڭ كېلەلمەيدۇ.","u yéngi ewlad chembirek padishahi dep atilidu, héchkim uninggha teng kélelmeydu."]],"桓桓":[["桓桓是个聪明又勤奋的孩子。","خۇەنخۇەن ئەقىللىق ۋە تىرىشچان بالىدۇر.","xuenxuen eqilliq we tirishchan balidur."]],"椰子":[["椰子是热带地区常见的水果。","كوكونۇت ئىسسىق بەلۋاغ رايونلىرىدا كۆپ ئۇچرايدىغان بىر خىل مېۋىدۇر.","kokonut issiq belwagh rayonlirida köp uchraydighan bir xil méwidur."]],"极品":[["这款手机是科技界的极品之作。","بۇ تېلېفون پەن-تېخنىكا دۇنياسىنىڭ ئەڭ ئالىي ئەسىرىدۇر.","bu téléfon pen-téxnika dunyasining eng aliy esiridur."]],"榜眼":[["他在科举考试中获得了榜眼。","ئۇ ئىمتىھاندا ئىككىنچى ئورۇننى ئالدى.","u imtihanda ikkinchi orunni aldi."]],"桩桩件件":[["桩桩件件都体现了匠心精神。","ئوقۇر-ئوقۇر ھەممىسى ئۇستىلىق روھىنى ئىپادىلەيدۇ.","oqur-oqur hemmisi ustiliq rohini ipadileydu."]],"条分缕析":[["他条分缕析地讲解了问题。","ئۇ مەسىلىنى تەپسىلىي تەھلىل قىلىپ چۈشەندۈردى.","u mesilini tepsiliy tehlil qilip chüshendürdi."]],"条条框框":[["这些条条框框限制了我的创作自由。","بۇ قائىدە-تۈزۈملەر مېنىڭ ئىجادىيەت ئەركىنلىكىمنى چەكلەپ قويدى.","bu qaide-tüzümler méning ijadiyet erkinlikimni cheklep qoydi."]],"楚汉战争":[["楚汉战争最终以刘邦胜利告终。","چۇ-خەن ئۇرۇشى ئاخىرىدا ليۇباڭنىڭ غەلىبىسى بىلەن ئاياغلاشتى.","chu-xen urushi axirida lyubangning ghelibisi bilen ayaghlashti."]],"概形":[["这个概形展示了整体结构。","بۇ ئومۇمىي شەكىل پۈتۈن قۇرۇلمىنى نامايان قىلىدۇ.","bu omumiy shekil pütün qurulmini namayan qilidu."]],"榛榛":[["榛榛是一种罕见的鸟类。","جېنجېن ناھايىتى ئاز ئۇچرايدىغان بىر قۇش تۈرىدۇر.","jénjén nahayiti az uchraydighan bir qush türidur."]],"桥接":[["桥接技术可连接不同网络。","كۆۋرۈكلەش تېخنىكىسى ئوخشىمىغان تورلارنى ئۇلايدۇ.","köwrüklesh téxnikisi oxshimighan torlarni ulaydu."]],"横越":[["他们横越了宽阔的河流。","ئۇلار كەڭ دەريادىن كۆندىلەڭ كېسىپ ئۆتتى.","ular keng deryadin köndileng késip ötti."]],"档口":[["档口是街头的小摊贩。","دوكو كوچا بويىدىكى كىچىك ساتقۇچىدۇر.","doko kocha boyidiki kichik satquchidur."]],"次大陆":[["次大陆的面积比大陆小。","كىچىك قۇرۇقلۇقنىڭ كۆلىمى چوڭ قۇرۇقلۇقتىن كىچىك.","kichik quruqluqning kölimi chong quruqluqtin kichik."]],"杠刀":[["杠刀是一种用于切割金属的工具。","گاڭداو مېتال كېسىشكە ئىشلىتىلىدىغان بىر خىل قورالدۇر.","gangdao métal késishke ishlitilidighan bir xil qoraldur."]],"台子":[["台子用来放置日常用品。","ئۈستەل كۈندىلىك بۇيۇملارنى قويۇشقا ئىشلىتىلىدۇ.","üstel kündilik buyumlarni qoyushqa ishlitilidu."]],"歌姬":[["古代歌姬常在宫廷中表演。","قەدىمكى ناخشىچىلار دائىم سارايدا ئويۇن قويىدۇ.","qedimki naxshichilar daim sarayda oyun qoyidu."]],"此致敬礼":[["此致敬礼，感谢您的支持。","ھۆرمەت بىلەن سالام، قوللىغانلىقىڭىزغا رەھمەت.","hörmet bilen salam, qollighanliqingizgha rehmet."]],"此处":[["此处风景优美，适合拍照。","بۇ يەرنىڭ مەنزىرىسى گۈزەل، سۈرەتكە تارتىشقا ماس كېلىدۇ.","bu yerning menzirisi güzel, süretke tartishqa mas kélidu."]],"武将":[["武将通常是军队的指挥官。","ۋۇجياڭ ئادەتتە ئارمىيەنىڭ قوماندانى.","wujyang adette armiyening qomandani."]],"武冈市":[["武冈市以美食文化闻名。","ۋۇگاڭ شەھىرى تائام مەدەنىيىتى بىلەن داڭلىق.","wugang shehiri taam medeniyiti bilen dangliq."]],"正正":[["正正之间，毫无偏差。","جېڭجېڭ ئارىسىدا، ھېچقانداق پەرق يوق.","jéngjéng arisida, héchqandaq perq yoq."]],"武隆":[["武隆是重庆市的一个区。","ۋۇلۇڭ چۇڭچىڭ شەھىرىنىڭ بىر رايونى.","wulung chungching shehirining bir rayoni."]],"步进制":[["计算机使用步进制进行计算。","كومپيۇتېر قەدەملىك سىستېما ئارقىلىق ھېسابلايدۇ.","kompyutér qedemlik sistéma arqiliq hésablaydu."]],"正太控":[["她是个典型的正太控。","ئۇ تىپىك بىر كىچىك ئوغۇل ھەۋەسكارى.","u tipik bir kichik oghul heweskari."]],"死死":[["他死死抓住机会不放。","ئۇ پۇرسەتنى قەتئىي چىڭ تۇتۇۋالدى.","u pursetni qet'iy ching tutuwaldi."]],"死活":[["无论死活都要完成任务。","ئۆلگەن-قالغان بولسىمۇ ۋەزىپىنى ئورۇنداش كېرەك.","ölgen-qalghan bolsimu wezipini orundash kérek."]],"死去":[["他最终因伤死去。","ئۇ ئاخىرى يارىسىدىن ئۆلدى.","u axiri yarisidin öldi."]],"殊域周咨录":[["《殊域周咨录》是古代游记。","«شۇيۈ جوۋزىلۇ» قەدىمكى سەييارەنامە.","«shuyü jowzilu» qedimki seyyarename."]],"母权制":[["母权制是一种古老的制度。","ئانا ھوقۇقلۇق تۈزۈم قەدىمىي بىر تۈزۈمدۇر.","ana hoquqluq tüzüm qedimiy bir tüzümdur."]],"毛茛":[["毛茛是一种观赏植物。","سېرىق گۈل بىر خىل مەنزىرە ئۆسۈملۈكى.","sériq gül bir xil menzire ösümlüki."]],"每逢佳节倍思亲":[["每逢佳节倍思亲，思念之情难以言表。","ھەر قېتىملىق بايرامدا ئۇرۇق-تۇغقانلارنى سېغىنىش تېخىمۇ كۈچىيىدۇ، سېغىنىش ھېسسىياتىنى تىل بىلەن ئىپادىلەش تەس.","her qétimliq bayramda uruq-tughqanlarni séghinish téximu küchiyidu, séghinish héssiyatini til bilen ipadilesh tes."]],"殷殷":[["他的眼神充满殷殷关切。","ئۇنىڭ كۆزلىرى چوڭقۇر غەمخورلۇققا تولغان.","uning közliri chongqur ghemxorluqqa tolghan."]],"残奥会":[["残奥会吸引了全球观众的关注。","مېيىپلار ئولىمپىك مۇسابىقىسى پۈتۈن دۇنيا تاماشىبىنلىرىنىڭ دىققىتىنى تارتىدى.","méyiplar olimpik musabiqisi pütün dunya tamashibinlirining diqqitini tartidi."]],"毛出在羊身上":[["羊毛出在羊身上。","قوي يۇڭى قويدىن چىقىدۇ.","qoy yungi qoydin chiqidu."]],"比年":[["他们比年长五岁。","ئۇلار بىر يىلدىن بەش ياش چوڭ.","ular bir yildin besh yash chong."]],"民生凋敝":[["战后民生凋敝，经济一片萧条。","ئۇرۇشتىن كېيىن خەلق تۇرمۇشى خارابلىشىپ، ئىقتىساد مۇتلەق تۇتۇقلىشىپ قالدى.","urushtin kéyin xelq turmushi xarabliship, iqtisad mutleq tutuqliship qaldi."]],"民丰县":[["民丰县位于新疆南部。","مىنفېڭ ناھىيىسى شىنجاڭنىڭ جەنۇبىدا جايلاشقان.","minféng nahiyisi shinjangning jenubida jaylashqan."]],"氯苯":[["氯苯属于芳香族化合物。","خلوروبېنزول خۇشپۇراقلىق بىرىكمىلەرگە تەۋە.","xlorobénzol xushpuraqliq birikmilerge tewe."]],"水气":[["潮湿的水气让玻璃窗变得模糊不清。","نەم ھاۋا ئەينەكنى تۇتۇق قىلىۋەتتى.","nem hawa eynekni tutuq qiliwetti."]],"永德县":[["永德县位于云南省的西南部。","يۇڭدې ناھىيىسى يۈننەن ئۆلكىسىنىڭ جەنۇبىي غەربىدە جايلاشقان.","yungdé nahiyisi yünnen ölkisining jenubiy gherbide jaylashqan."]],"求欢":[["他试图用礼物求欢。","ئۇ سوۋغات بىلەن كۆڭلىنى ئېلىشقا ئۇرۇندى.","u sowghat bilen könglini élishqa urundi."]],"江达县":[["江达县位于四川省的北部地区。","جياڭدا ناھىيىسى سىچۇەن ئۆلكىسىنىڭ شىمالىي قىسمىدا جايلاشقان.","jyangda nahiyisi sichuen ölkisining shimaliy qismida jaylashqan."]],"没水平":[["他的技术没水平。","ئۇنىڭ تېخنىكىسىنىڭ سەۋىيىسى يوق.","uning téxnikisining sewiyisi yoq."]],"沉浸式":[["这款游戏体验极具沉浸式。","بۇ ئويۇننىڭ تەجرىبىسى ئىنتايىن چۆمۈلدۈرۈش خاراكتېرلىك.","bu oyunning tejribisi intayin chömüldürüsh xaraktérlik."]],"油油":[["头发油油的，需要清洗。","چېچى يېغلىق، يۇيۇشقا توغرا كېلىدۇ.","chéchi yéghliq, yuyushqa toghra kélidu."]],"沿儿":[["沿儿处常常积水。","گىرۋەك جايلاردا كۆپىنچە سۇ يىغىلىپ قالىدۇ.","girwek jaylarda köpinche su yighilip qalidu."]],"泔水":[["泔水不能直接倒入河流。","ئاشخانا سۈيىنى بىۋاسىتە دەرياغا تۆكۈشكە بولمايدۇ.","ashxana süyini biwasite deryagha töküshke bolmaydu."]],"油船":[["油船在海上航行，运送大量石油。","ماي كېمىسى دېڭىزدا يۈزۈپ، كۆپ مىقداردا نېفىت توشۇيدۇ.","may kémisi déngizda yüzüp, köp miqdarda néfit toshuydu."]],"沉积带":[["沉积带富含多种矿物质资源。","چۆكمە بەلبېغى تۈرلۈك مىنېرال بايلىقلارغا باي.","chökme belbéghi türlük minéral bayliqlargha bay."]],"求索":[["人类一直在求索真理。","ئىنسانىيەت ھەمىشە ھەقىقەتنى ئىزدەپ كەلدى.","insaniyet hemishe heqiqetni izdep keldi."]],"波茨坦":[["波茨坦是德国的城市。","پوتسدام گېرمانىيەنىڭ بىر شەھىرى.","potsdam gérmaniyening bir shehiri."]],"波兹南":[["波兹南是波兰的重要城市。","پوزنان پولشانىڭ مۇھىم شەھىرى.","poznan polshaning muhim shehiri."]],"波昂":[["波昂是葡萄牙的首都。","لىسبون پورتۇگالىيەنىڭ پايتەختى.","lisbon portugaliyening paytexti."]],"泡澡":[["他每天晚上都会泡澡放松。","ئۇ ھەر كۈنى كەچتە چۆمۈلۈپ بوي ئېلىشىدۇ.","u her küni kechte chömülüp boy élishidu."]],"法医学":[["法医学是结合医学与法律的学科。","قانۇن تېببىي ئىلمى تېببىي ئىلىم بىلەن قانۇننى بىرلەشتۈرگەن پەن.","qanun tébbiy ilmi tébbiy ilim bilen qanunni birleshtürgen pen."]],"泡泡":[["肥皂水能吹出五彩泡泡。","سوپۇن سۈيى رەڭدار كۆپۈكلەرنى چىقىرىدۇ.","sopun süyi rengdar köpüklerni chiqiridu."]],"法式色拉酱":[["法式色拉酱搭配沙拉非常美味。","فىرانسۇسچە سالات قىيامى سالات بىلەن ئىنتايىن لەززەتلىك.","firansusche salat qiyami salat bilen intayin lezzetlik."]],"津津":[["他对这件事津津乐道。","ئۇ بۇ ئىش توغرىسىدا قىزىقىپ سۆزلەيدۇ.","u bu ish toghrisida qiziqip sözleydu."]],"泄愤":[["他大声怒吼以泄愤。","ئۇ ئاۋازىنى كۆتۈرۈپ ۋارقىراپ غەزىپىنى چىقىرىدۇ.","u awazini kötürüp warqirap ghezipini chiqiridu."]],"洋芋":[["今天炒了洋芋丝。","بۈگۈن ياڭيۇ تىلىمى قورۇلدى.","bügün yangyu tilimi qoruldi."]],"洱源县":[["洱源县出产优质的茶叶和药材。","ئېريۈەن ناھىيىسى ئەلا سۈپەتلىك چاي ۋە دورا ماتېرىياللىرىنى ئىشلەپچىقىرىدۇ.","éryüen nahiyisi ela süpetlik chay we dora matériyallirini ishlepchiqiridu."]],"流浪汉":[["流浪汉的生活十分艰难。","ئاقار سەرگەردانلارنىڭ تۇرمۇشى ئىنتايىن قىيىن.","aqar sergerdanlarning turmushi intayin qiyin."]],"流动率":[["工厂的流动率提高了百分之十。","زاۋۇتنىڭ ئېقىم نىسبىتى ئون پىرسەنت ئۆستى.","zawutning éqim nisbiti on pirsent östi."]],"浣衣":[["浣衣是传统手工艺之一。","كىيىم يۇيۇش ئەنئەنىۋى قول ھۈنەرلىرىنىڭ بىرىدۇر.","kiyim yuyush en'eniwi qol hünerlirining biridur."]],"浪得虚名":[["他不过是浪得虚名，并无真才实学。","ئۇ پەقەت نامىلا سەرسان، ھەقىقىي ئىلىمى يوق.","u peqet namila sersan, heqiqiy ilimi yoq."]],"海底捞":[["海底捞以其独特的火锅服务闻名。","دېڭىز ئاستى قازانچىسى ئۆزىگە خاس قازان مۇلازىمىتى بىلەن تونۇلغان.","déngiz asti qazanchisi özige xas qazan mulazimiti bilen tonulghan."]],"海康":[["海康公司的摄像头质量非常好。","خەيكاڭ شىركىتىنىڭ كامېرا سۈپىتى ناھايىتى ياخشى.","xeykang shirkitining kaméra süpiti nahayiti yaxshi."]],"海德":[["海德是一位著名的哲学家。","خەيدې مەشھۇر پەلسەپىشۇناس.","xeydé meshhur pelsepishunas."]],"涂尔干":[["涂尔干是著名的社会学家。","دۇركخېيم مەشھۇر سوتسىيولوگ ئىدى.","durkxéym meshhur sotsiyolog idi."]],"浮华":[["浮华的外表掩盖了内在的空虚。","جەۋھەرسىز يۈز ئىچكى بوشلۇقنى يوشۇرغان.","jewhersiz yüz ichki boshluqni yoshurghan."]],"涉黑案":[["这起涉黑案已结案。","بۇ قارا جەمئىيەتكە چېتىلىدىغان ئىش ئاخىرلاشتى.","bu qara jem'iyetke chétilidighan ish axirlashti."]],"涓涓":[["溪水涓涓流淌。","ئېرىق سۈيى سىلدىراپ ئېقىۋاتىدۇ.","ériq süyi sildirap éqiwatidu."]],"凉凉":[["这首歌的旋律听起来凉凉。","بۇ ناخشىنىڭ ئاھاڭى ئاڭلىغاندا سالقىنلىق تۇيۇلدۇرىدۇ.","bu naxshining ahangi anglighanda salqinliq tuyulduridu."]],"凉粉":[["凉粉口感滑爽，清凉解暑。","سالقىن ئۇن تامىقىنىڭ تەمى تىپتىنچە، سالقىنلىق بېرىپ ئىسسىقنى يېنىكلىتىدۇ.","salqin un tamiqining temi tiptinche, salqinliq bérip issiqni yéniklitidu."]],"涿鹿":[["涿鹿是河北省的一个古老县。","جوجۇلۇ خېبېي ئۆلكىسىدىكى قەدىمىي بىر ناھىيە.","jojulu xébéy ölkisidiki qedimiy bir nahiye."]],"海运费":[["海运费根据货物重量和目的地计算。","دېڭىز توشۇش ھەققى يۈك ئېغىرلىقى ۋە مەنزىلگە ئاساسەن ھېسابلىنىدۇ.","déngiz toshush heqqi yük éghirliqi we menzilge asasen hésablinidu."]],"深圳市":[["深圳市位于广东省。","شېنجېن شەھىرى گۇاڭدۇڭ ئۆلكىسىدە جايلاشقان.","shénjén shehiri guangdung ölkiside jaylashqan."]],"深爱":[["她深爱着自己的丈夫。","ئۇ ئۆز ئېرىنى چوڭقۇر سۆيىدۇ.","u öz érini chongqur söyidu."]],"浩浩":[["河水浩浩奔流不息。","دەريا سۈيى توختىماي ئېقىپ ئاقىدۇ.","derya süyi toxtimay éqip aqidu."]],"清河门区":[["清河门区是市内的一个行政区。","چىڭخېمېن رايونى شەھەر ئىچىدىكى بىر مەمۇرىي رايوندۇر.","chingxémén rayoni sheher ichidiki bir memuriy rayondur."]],"淡绿鵙鹛":[["淡绿鵙鹛栖息在茂密的森林中。","بۇ قۇش قويۇق ئورمانلاردا ياشايدۇ.","bu qush qoyuq ormanlarda yashaydu."]],"涣散":[["团队如果涣散，就很难取得成就。","ئەگەر گۇرۇپپا تارقاق بولسا، نەتىجە قازىنىش قىيىن بولىدۇ.","eger guruppa tarqaq bolsa, netije qazinish qiyin bolidu."]],"消耗量":[["今年的能源消耗量增加了。","بۇ يىلنىڭ ئېنېرگىيە سەرپىياتى ئاشتى.","bu yilning énérgiye serpiyati ashti."]],"海魂衫":[["海魂衫是经典的服装。","دېڭىز روھى كۆڭلىكى كلاسسىك كىيىمدۇر.","déngiz rohi köngliki klassik kiyimdur."]],"湉湉":[["湉湉是一条清澈的小溪。","تيەنتيەن سۈزۈك بىر كىچىك ئېقىن.","tyentyen süzük bir kichik éqin."]],"凑近":[["他凑近看了看桌上的照片。","ئۇ يېقىنلىشىپ ئۈستەلدىكى سۈرەتكە قارىدى.","u yéqinliship üsteldiki süretke qaridi."]],"减小":[["音量可以减小一些。","ئاۋازنى بىر ئاز كىچىكلىتىشكە بولىدۇ.","awazni bir az kichiklitishke bolidu."]],"港珠澳大桥":[["港珠澳大桥是世界级工程。","شياڭگاڭ-زۇخەي-ئاۋمېن كۆۋرۈكى دۇنيا دەرىجىلىك قۇرۇلۇشتۇر.","shyanggang-zuxey-awmén köwrüki dunya derijilik qurulushtur."]],"溶化":[["糖在热水中迅速溶化。","شېكەر ئىسسىق سۇدا تېز ئېرىيدۇ.","shéker issiq suda téz ériydu."]],"滋事":[["他在街上故意滋事。","ئۇ كوچىدا قەستەن قالايمىقانچىلىق قىلدى.","u kochida qesten qalaymiqanchiliq qildi."]],"温温":[["天气温温的，正是出游的好时节。","ھاۋا مۇلايىم ئىسسىق، دەل سەپەرگە چىقىدىغان ياخشى پەسىل.","hawa mulayim issiq, del seperge chiqidighan yaxshi pesil."]],"温室废气储存":[["温室废气储存技术有助于减少排放。","ئىسسىقخانا ئەخلەت گازى ساقلاش تېخنىكىسى ئايرىلىشنى ئازايتىشقا ياردەم بېرىدۇ.","issiqxana exlet gazi saqlash téxnikisi ayrilishni azaytishqa yardem béridu."]],"沪上":[["沪上指的是上海地区。","خۇشاڭ شاڭخەي رايونىنى كۆرسىتىدۇ.","xushang shangxey rayonini körsitidu."]],"漾濞":[["漾濞的风景非常迷人。","ياڭبىنىڭ مەنزىرىسى ئىنتايىن جەلپكار.","yangbining menzirisi intayin jelpkar."]],"漳平":[["漳平以优质的茶叶和自然风光闻名。","جاڭپىڭ ئەلا سۈپەتلىك چاي ۋە تەبىئىي مەنزىرىسى بىلەن داڭلىق.","jangping ela süpetlik chay we tebiiy menzirisi bilen dangliq."]],"溆浦":[["溆浦县地处湖南省西部山区。","شۈپۇ ناھىيىسى خۇنەن ئۆلكىسىنىڭ غەربىي تاغلىق رايونىدا جايلاشقان.","shüpu nahiyisi xunen ölkisining gherbiy taghliq rayonida jaylashqan."]],"滴答":[["手表发出规律的滴答声。","قول سائەت مۇنتىزىم تىق-تىق ئاۋاز چىقىرىدۇ.","qol saet muntizim tiq-tiq awaz chiqiridu."]],"濯濯":[["阳光照耀下，河水显得濯濯发光。","قۇياش نۇرىنىڭ چۈشۈشىدە دەريا سۈيى پارقىراپ كۆرۈندى.","quyash nurining chüshüshide derya süyi parqirap köründi."]],"火烫":[["他的手被火烫得通红。","ئۇنىڭ قولى ئوتتا كۆيۈپ قىپقىزىل بولۇپ كەتتى.","uning qoli otta köyüp qipqizil bolup ketti."]],"灰背隼":[["灰背隼在空中快速飞行。","كۈمۈشسىمان ئارقا لاچىنى ھاۋادا تېز ئۇچىدۇ.","kümüshsiman arqa lachini hawada téz uchidu."]],"灰蓝姬鹟":[["灰蓝姬鹟在枝头鸣唱。","كۈمۈشسىمان كۆك چىمچىقى شاخ ئۈستىدە سايرايدۇ.","kümüshsiman kök chimchiqi shax üstide sayraydu."]],"焊枪":[["焊枪是焊接操作中的常用工具。","پەيۋەز پىستولېتى پەيۋەزلەش مەشغۇلاتىدىكى كۆپ ئىشلىتىلىدىغان قورال.","peywez pistoléti peywezlesh meshghulatidiki köp ishlitilidighan qoral."]],"为人师表":[["老师要为人师表。","ئوقۇتقۇچى ئادەملەرگە ئۈلگە بولۇشى كېرەك.","oqutquchi ademlerge ülge bolushi kérek."]],"无人区":[["这片无人区充满未知危险。","بۇ ئادەم يوق رايون نامەلۇم خەتەرلەرگە تولغان.","bu adem yoq rayon namelum xeterlerge tolghan."]],"无人机":[["无人机被广泛用于军事侦察。","ئادەمسىز ئۇچقۇ ھەربىي بېكىتىش ئىشلىرىدا كەڭ قوللىنىلىدۇ.","ademsiz uchqu herbiy békitish ishlirida keng qollinilidu."]],"无人飞行器":[["无人飞行器正在执行任务。","ئادەمسىز ئۇچقۇ ۋەزىپە ئىجرا قىلماقتا.","ademsiz uchqu wezipe ijra qilmaqta."]],"煽动颠覆国家罪":[["煽动颠覆国家罪会被依法惩处。","دۆلەت ھاكىمىيىتىنى ئاغدۇرۇشقا قۇترىتىش جىنايىتى قانۇن بويىچە جازالىنىدۇ.","dölet hakimiyitini aghdurushqa qutritish jinayiti qanun boyiche jazalinidu."]],"熊倪":[["熊倪是一位著名的跳水运动员。","شوڭ نى مەشھۇر سۇغا سەكرەش تەنھەرىكەتچىسى.","shong ni meshhur sugha sekresh tenheriketchisi."]],"熟食":[["超市里的熟食区人很多。","سۇپېرماركېتتىكى پىششىق يېمەكلىك رايونىدا ئادەم كۆپ.","supérmarkéttiki pishshiq yémeklik rayonida adem köp."]],"熠耀":[["太阳熠耀，温暖了大地。","قۇياش پارقىراپ، زېمىننى ئىسسىتتى.","quyash parqirap, zéminni issitti."]],"营工":[["营工负责工程搭建。","قۇرۇلۇش ئىشچىسى قۇرۇلۇش قۇرۇش ئۈچۈن مەسئۇل.","qurulush ishchisi qurulush qurush üchün mes'ul."]],"无着":[["行李无着令人十分困扰。","يۈك-تاقنىڭ جايلىشالماسلىقى كىشىنى ئىنتايىن ئاۋارە قىلىدۇ.","yük-taqning jaylishalmasliqi kishini intayin aware qilidu."]],"无言":[["他站在那里，无言以对。","ئۇ ئۇ يەردە تۇرۇپ، ئېيتقىلى سۆز تېپەلمىدى.","u u yerde turup, éytqili söz tépelmidi."]],"牛毛":[["牛毛可以用来做刷子。","كالا يۇڭى چوتكا ياساشقا ئىشلىتىلىدۇ.","kala yungi chotka yasashqa ishlitilidu."]],"燃眉之急":[["解决燃眉之急是当前的首要任务。","قاش قارىغۇچىلىق قىيىنچىلىقىنى ھەل قىلىش ھازىرقى بىرىنچى نۆۋەتلىك ۋەزىپە.","qash qarighuchiliq qiyinchiliqini hel qilish hazirqi birinchi nöwetlik wezipe."]],"争妍斗艳":[["舞台上，演员们争妍斗艳，大放异彩。","سەھنىدە، ئارتىسلار گۈزەللىكتە مۇسابىقىلىشىپ، پارلاق نۇمۇيۇش قىلدى.","sehnide, artislar güzellikte musabiqiliship, parlaq numuyush qildi."]],"猛进":[["项目进展猛进。","تۈر ئىلگىرىلەشى تېز ئىلگىرىلىدى.","tür ilgirileshi téz ilgirilidi."]],"玉泉":[["玉泉是历史悠久的名胜古迹。","يۈچۈەن ئۇزۇن تارىخقا ئىگە داڭلىق تارىخىي ئورۇن.","yüchüen uzun tarixqa ige dangliq tarixiy orun."]],"玉珉":[["玉珉是一种质地细腻的玉石。","يۈمىن نەپىس توقۇلمىلىق بىر خىل قاشتېشى.","yümin nepis toqulmiliq bir xil qashtéshi."]],"猛不防":[["他猛不防被偷袭，措手不及。","ئۇ تۇيۇقسىز بېسىپ كېلىشكە ئۇچراپ، ھېچقانداق تەييارلىقسىز قالدى.","u tuyuqsiz bésip kélishke uchrap, héchqandaq teyyarliqsiz qaldi."]],"猛力":[["他用猛力一推，门应声而开。","ئۇ كۈچ بىلەن ئىتتىرىپ، ئىشىك دەرھال ئېچىلدى.","u küch bilen ittirip, ishik derhal échildi."]],"珍重":[["请珍重身体，不要过度劳累。","سالامەتلىكىڭىزنى قەدرلىڭ، ھەددىدىن زىيادە چارچىماڭ.","salametlikingizni qedrling, heddidin ziyade charchimang."]],"玩物":[["这些玩物都是古董收藏品。","بۇ ئويۇن بۇيۇملىرىنىڭ ھەممىسى قەدىمكى زامان يىغىمچىلىق بۇيۇملىرى.","bu oyun buyumlirining hemmisi qedimki zaman yighimchiliq buyumliri."]],"琐记":[["琐记记录了他日常生活中的点滴。","ئۇششاق خاتىرىلەر ئۇنىڭ كۈندىلىك تۇرمۇشىدىكى ئۇششاق ئىشلارنى خاتىرىلىگەن.","ushshaq xatiriler uning kündilik turmushidiki ushshaq ishlarni xatiriligen."]],"瓶盖":[["瓶盖需要密封性好。","ئاپتوق قاپقىقىنىڭ پېچەتلىشىش خۇسۇسىيىتى ياخشى بولۇشى كېرەك.","aptoq qapqiqining péchetlishish xususiyiti yaxshi bolushi kérek."]],"珉玉":[["珉玉是一种珍贵的宝石。","مىن يۈ قىممەتلىك بىر گۆھەردۇر.","min yü qimmetlik bir göherdur."]],"瑞典人":[["瑞典人普遍讲瑞典语。","شۋېتسىيەلىكلەر ئومۇمەن شۋېتسىيە تىلىدا سۆزلىشىدۇ.","shwétsiyelikler omumen shwétsiye tilida sözlishidu."]],"申申":[["申申这个名字听起来很亲切。","شېنشېن دېگەن بۇ ئىسىم ئاڭلىماققا ئىنتايىن ئىللىق تۇيۇلىدۇ.","shénshén dégen bu isim anglimaqqa intayin illiq tuyulidu."]],"留给":[["他把礼物留给了朋友。","ئۇ سوۋغىنى دوستىغا قالدۇرۇپ قويدى.","u sowghini dostigha qaldurup qoydi."]],"异化作用":[["异化作用在生物进化中起关键作用。","ئەلگىنىش رولى بىئولوگىيەلىك تەرەققىياتتا ھالقىلىق رول ئوينايدۇ.","elginish roli biologiyelik tereqqiyatta halqiliq rol oynaydu."]],"异形":[["这种外星生物是典型的异形。","بۇ تاشقى پلانېتا جانلىقى تىپىك غەلىتە شەكىل.","bu tashqi planéta janliqi tipik ghelite shekil."]],"画画":[["孩子们喜欢在课余时间画画。","بالىلار دەرستىن سىرتقى ۋاقىتلاردا رەسىم سىزىشنى ياخشى كۆرىدۇ.","balilar derstin sirtqi waqitlarda resim sizishni yaxshi köridu."]],"畔援":[["他得到畔援。","ئۇ ياردەمگە ئېرىشتى.","u yardemge érishti."]],"痛心疾首":[["看到国家动荡，我痛心疾首。","دۆلەتنىڭ قالايمىقانچىلىققا چۆمگەنلىكىنى كۆرۈپ، يۈرىكىم ئېزىلدى.","döletning qalaymiqanchiliqqa chömgenlikini körüp, yürikim ézildi."]],"癫痫":[["他从小就有癫痫的病史。","ئۇ كىچىكىدىن تارتىپ ساراڭ كېسىلىنىڭ كېسەللىك تارىخىغا ئىگە.","u kichikidin tartip sarang késilining késellik tarixigha ige."]],"疑云":[["事件背后笼罩着疑云。","ۋەقە ئارقىسىدا گۇمانلىق ھالەت قاپلىماقتا.","weqe arqisida gumanliq halet qaplimaqta."]],"白领凤鹛":[["白领凤鹛的叫声清脆悦耳。","ئاق ياقىلىق فېڭمېينىڭ سايرىشى سۈزۈك ۋە يېقىملىق.","aq yaqiliq féngméyning sayrishi süzük we yéqimliq."]],"白颈鸫":[["白颈鸫喜欢在树上觅食。","ئاق بوينىلىق سەۋزە دەرەخلەردە يېمەكلىك ئىزدەشنى ياخشى كۆرىدۇ.","aq boyniliq sewze derexlerde yémeklik izdeshni yaxshi köridu."]],"百科事典":[["参考这本百科事典，能学到很多知识。","بۇ ئېنسىكلوپېدىيە لۇغىتىگە قاراپ، نۇرغۇن بىلىم ئېلىشقا بولىدۇ.","bu énsiklopédiye lughitige qarap, nurghun bilim élishqa bolidu."]],"磨磨蹭蹭":[["他磨磨蹭蹭，效率很低。","ئۇ ئىشنى سۇستىلىق بىلەن قىلىپ، ئۈنۈمى ئىنتايىن تۆۋەن.","u ishni sustiliq bilen qilip, ünümi intayin töwen."]],"矻矻":[["他矻矻地工作了一整天。","ئۇ پۈتۈن كۈنى تىرىشىپ ئىشلىدى.","u pütün küni tiriship ishlidi."]],"短语":[["这个短语很常用。","بۇ ئىبارە ئىنتايىن كۆپ ئىشلىتىلىدۇ.","bu ibare intayin köp ishlitilidu."]],"穿凿":[["这个故事有些穿凿附会。","بۇ ھېكايە بىر ئاز زورلاشقان ۋە ئەسلىسىز.","bu hékaye bir az zorlashqan we eslisiz."]],"纸包饮品":[["纸包饮品方便携带。","قەغەز قاپلىق ئىچىملىك ئېلىپ يۈرۈشكە قولايلىق.","qeghez qapliq ichimlik élip yürüshke qolayliq."]],"累犯":[["他因累犯被判处更重刑罚。","ئۇ تەكرار جىنايەتچى بولغانلىقى ئۈچۈن ئېغىرراق جازاغا ھۆكۈم قىلىندى.","u tekrar jinayetchi bolghanliqi üchün éghirraq jazagha höküm qilindi."]],"累积":[["数据需要持续累积分析。","سانلىق مەلۇماتلارنى داۋاملىق توپلاپ تەھلىل قىلىش كېرەك.","sanliq melumatlarni dawamliq toplap tehlil qilish kérek."]],"累累":[["他满身累累伤痕令人心疼。","ئۇنىڭ بەدىنى يارا-يارا، بۇ كىشىنىڭ يۈرىكىنى ئېچىتتى.","uning bedini yara-yara, bu kishining yürikini échitti."]],"索求":[["他向政府索求更多的社会资源。","ئۇ ھۆكۈمەتتىن تېخىمۇ كۆپ ئىجتىمائىي بايلىق تەلەپ قىلدى.","u hökümettin téximu köp ijtimaiy bayliq telep qildi."]],"索尔兹伯里石环":[["索尔兹伯里石环是英国的史前巨石阵。","سولزبېرى تاش چەمبىرى ئەنگلىيەنىڭ تارىختىن ئىلگىرىكى زور تاشلىرىدۇر.","solzbéri tash chembiri engliyening tarixtin ilgiriki zor tashliridur."]]};
